# v20: E156 perception/planner core only. This module owns NO camera/model/serial/UI.
# Load the core file that shares this main file's _vNN suffix.  This prevents a copied
# next-version main from silently importing an older hard-coded core module.  A stable
# unversioned filename is accepted as a deployment fallback; otherwise MICRO fails closed.
def _load_matching_micro_unfold_core():
    here = os.path.dirname(os.path.abspath(__file__))
    basename = os.path.basename(__file__)
    match = re.search(r"_v(\d+)\.py$", basename)
    candidates = []
    if match:
        candidates.append(f"micro_unfold_e156_core_v{match.group(1)}.py")
    candidates.append("micro_unfold_e156_core_v21.py")
    candidates.append("micro_unfold_e156_core.py")
    errors = []
    seen = set()
    for filename in candidates:
        if filename in seen:
            continue
        seen.add(filename)
        core_path = os.path.join(here, filename)
        if not os.path.isfile(core_path):
            errors.append(f"missing:{filename}")
            continue
        module_name = f"_e156_micro_core_{os.path.splitext(filename)[0]}"
        try:
            spec = importlib.util.spec_from_file_location(module_name, core_path)
            if spec is None or spec.loader is None:
                raise ImportError(f"cannot create import spec for {core_path}")
            module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(module)
            return module, None, core_path
        except Exception as exc:
            errors.append(f"{filename}:{exc!r}")
    return None, RuntimeError("MICRO_UNFOLD core load failed: " + " | ".join(errors)), None

e156_micro_core, _MICRO_UNFOLD_CORE_IMPORT_ERROR, _MICRO_UNFOLD_CORE_PATH = _load_matching_micro_unfold_core()

