# A140 orchestration-only action classes.  These sets classify the result of the
# existing A139 planner; they do not change choose_action() or any READY/CCA rule.
AUTO_X_INTERNAL_REJUDGE_ACTIONS = frozenset({
    "ACTION2_PLAN_RETRY_REQUIRED",
    "ACTION2_GRAY_REJUDGE",
    "ACTION2_COUNT_CLEANUP_REJUDGE",
    "ACTION3_PLAN_RETRY_REQUIRED",
    "ACTION3_GRAY_REJUDGE",
    "POSE_REJUDGE_REQUIRED",
    "NEAR_READY_CONFIRM",
    "NO_ACTION_CANDIDATE",
    "WORKSPACE_REJUDGE_REQUIRED",
    "LATE_REJUDGE_REQUIRED",
    "LATE_POSE_SOFT_REJUDGE",
    "LATE_STRUCTURAL_CONFIRMED_REJUDGE",
    # v12 explicit ROTATE observation reasons.  Legacy name remains accepted for old logs only.
    "ROTATE_POSE_RETRY_REQUIRED",
    "ROTATE_FALLBACK_CONFIRM_REJUDGE",
    "ROTATE_ANGLE_CONFIRM_REJUDGE",
    "ROTATE_POSE_CONSENSUS_REJUDGE",
})
AUTO_X_TERMINAL_ACTIONS = frozenset({"STOP", "FINISH_READY_FOR_ROTATION"})
AUTO_X_NON_EXECUTABLE_ACTIONS = AUTO_X_INTERNAL_REJUDGE_ACTIONS | AUTO_X_TERMINAL_ACTIONS


class A140AutoXController:
    """Small, device-independent AUTO-X cycle state reducer.

    Physical execution is deliberately outside this class.  The controller can
    request a fresh judgment, but it has no API that can execute an action.
    """

    def __init__(self, internal_rejudge_enable: bool = True,
                 internal_rejudge_max_attempts: int = 2,
                 internal_rejudge_delay_s: float = 0.10):
        self._lock = threading.RLock()
        self.internal_rejudge_enable = bool(internal_rejudge_enable)
        # A143: keep a finite guard. The second consecutive rejudge-like result
        # is normally converted to an A136-style light one-arm nudge before this limit.
        self.internal_rejudge_max_attempts = int(internal_rejudge_max_attempts)
        self.internal_rejudge_delay_s = max(0.0, float(internal_rejudge_delay_s))
        self.cycle_number = 0
        self.armed = False
        self.state = "IDLE"
        self.post_action_rejudge_requested = False
        self.internal_rejudge_requested = False
        self.internal_rejudge_attempt = 0
        self.internal_rejudge_origin: Optional[str] = None
        self.last_nonexec_action: Optional[str] = None
        self.last_nonexec_reason = ""
        self.last_executed_action = ""
        self.rejudge_not_before = 0.0
        self.last_error = ""
        self.epoch = 0

    def configure(self, enabled: bool, max_attempts: int, delay_s: float) -> None:
        with self._lock:
            self.internal_rejudge_enable = bool(enabled)
            self.internal_rejudge_max_attempts = int(max_attempts)
            self.internal_rejudge_delay_s = max(0.0, float(delay_s))

    def reset_internal_counter(self) -> None:
        with self._lock:
            self.internal_rejudge_attempt = 0
            self.last_nonexec_action = None
            self.last_nonexec_reason = ""

    def arm_manual(self) -> str:
        with self._lock:
            first = not self.armed
            if first:
                self.cycle_number += 1
            # Every manual X supersedes any older in-flight judge result.
            self.epoch += 1
            self.armed = True
            self.state = "JUDGING"
            self.post_action_rejudge_requested = False
            self.internal_rejudge_requested = False
            self.internal_rejudge_origin = "MANUAL_X"
            self.rejudge_not_before = 0.0
            self.last_error = ""
            self.internal_rejudge_attempt = 0
            self.last_nonexec_action = None
            self.last_nonexec_reason = ""
            return "ARMED" if first else "MANUAL_FORCE_REJUDGE"

    def arm_automatic(self) -> str:
        """Arm one continuous garment cycle without a manual X key press."""
        with self._lock:
            first = not self.armed
            if first:
                self.cycle_number += 1
            self.epoch += 1
            self.armed = True
            self.state = "JUDGING"
            self.post_action_rejudge_requested = False
            self.internal_rejudge_requested = False
            self.internal_rejudge_origin = "AUTO_IDLE"
            self.rejudge_not_before = 0.0
            self.last_error = ""
            self.internal_rejudge_attempt = 0
            self.last_nonexec_action = None
            self.last_nonexec_reason = ""
            return "AUTO_ARMED" if first else "AUTO_FORCE_REJUDGE"

    def action_started(self, expected_epoch: int) -> bool:
        with self._lock:
            if (not self.armed or int(expected_epoch) != int(self.epoch)
                    or self.state != "EXECUTING"):
                return False
            self.post_action_rejudge_requested = False
            self.internal_rejudge_requested = False
            return True

    def claim_physical_approval(self) -> Optional[int]:
        with self._lock:
            if not self.armed or self.state != "WAITING_ENTER":
                return None
            self.state = "EXECUTING"
            self.post_action_rejudge_requested = False
            self.internal_rejudge_requested = False
            return int(self.epoch)

    def restore_physical_approval(self, expected_epoch: int) -> None:
        with self._lock:
            if self.armed and int(expected_epoch) == int(self.epoch) and self.state == "EXECUTING":
                self.state = "WAITING_ENTER"

    def schedule_post_action(self, action: str, now: float, settle_s: float = 0.0,
                             expected_epoch: Optional[int] = None,
                             publisher=None) -> bool:
        with self._lock:
            if (not self.armed
                    or (expected_epoch is not None and int(expected_epoch) != int(self.epoch))
                    or self.state != "EXECUTING"):
                return False
            self.last_executed_action = str(action)
            self.internal_rejudge_attempt = 0
            self.last_nonexec_action = None
            self.last_nonexec_reason = ""
            self.post_action_rejudge_requested = True
            self.internal_rejudge_requested = False
            self.internal_rejudge_origin = "POST_ACTION"
            self.rejudge_not_before = float(now) + max(0.0, float(settle_s))
            self.state = "POST_ACTION_STANDBY"
            self.last_error = ""
            if publisher is not None:
                publisher()
            return True

    def complete_action_wait_manual_x(self, action: str,
                                      expected_epoch: Optional[int] = None,
                                      publisher=None) -> bool:
        """Finish one successful physical action without scheduling a judgment.

        A141 compatibility method retained; A142 normal flow uses schedule_post_action().
        """
        with self._lock:
            if (not self.armed
                    or (expected_epoch is not None and int(expected_epoch) != int(self.epoch))
                    or self.state != "EXECUTING"):
                return False
            self.last_executed_action = str(action)
            self.internal_rejudge_attempt = 0
            self.last_nonexec_action = None
            self.last_nonexec_reason = ""
            self.post_action_rejudge_requested = False
            self.internal_rejudge_requested = False
            self.internal_rejudge_origin = None
            self.rejudge_not_before = 0.0
            self.state = "WAITING_MANUAL_X"
            self.last_error = ""
            if publisher is not None:
                publisher()
            return True

    @_pipeline_v2.scheduled_result
    def invalidate_target_schedule_rejudge(self, reason: str, now: float,
                                            delay_s: float = 0.0,
                                            publisher=None, expected_epoch: Optional[int] = None) -> bool:
        """Discard a stale frozen target and automatically obtain a new still snapshot."""
        with self._lock:
            if not self.armed or (expected_epoch is not None and int(expected_epoch) != int(self.epoch)):
                return False
            # Supersede the stale pending/judge generation while preserving the
            # garment action count, Late tracks, structural memory, and log cycle.
            self.epoch += 1
            self.post_action_rejudge_requested = False
            self.internal_rejudge_requested = True
            self.internal_rejudge_origin = "TARGET_INVALIDATED"
            self.last_nonexec_action = "TARGET_INVALIDATED"
            self.last_nonexec_reason = str(reason)
            self.rejudge_not_before = float(now) + max(0.0, float(delay_s))
            self.last_error = str(reason)
            self.state = "INTERNAL_REJUDGING"
            if publisher is not None:
                publisher()
            return True

    def handle_planner_result(self, action: str, reason: str, now: float,
                              expected_epoch: Optional[int] = None,
                              terminal_publisher=None) -> Dict[str, Any]:
        with self._lock:
            action = str(action)
            reason = str(reason)
            if (not self.armed
                    or (expected_epoch is not None and int(expected_epoch) != int(self.epoch))):
                return {"kind": "cancelled", "action": action, "state": self.state, "scheduled": False}
            if action in AUTO_X_TERMINAL_ACTIONS:
                terminal_state = "READY" if action == "FINISH_READY_FOR_ROTATION" else "STOPPED"
                self._disarm_locked(action, terminal_state)
                if terminal_publisher is not None:
                    terminal_publisher()
                return {"kind": "terminal", "action": action, "state": self.state, "scheduled": False}
            if action in AUTO_X_INTERNAL_REJUDGE_ACTIONS:
                # v12: ROTATE observation requests are semantically distinct and each
                # receives at most ONE fresh observation.  A Pose retry must not borrow
                # the generic 2-attempt budget, and a subsequent low-trust/angle
                # confirmation gets its own independent one-shot budget.
                rotate_single_rejudge = action in {
                    "ROTATE_POSE_RETRY_REQUIRED",
                    "ROTATE_FALLBACK_CONFIRM_REJUDGE",
                    "ROTATE_ANGLE_CONFIRM_REJUDGE",
                    "ROTATE_POSE_CONSENSUS_REJUDGE",  # historical compatibility only
                }
                if rotate_single_rejudge and self.last_nonexec_action != action:
                    self.internal_rejudge_attempt = 0
                action_limit = 1 if rotate_single_rejudge else int(self.internal_rejudge_max_attempts)
                self.last_nonexec_action = action
                self.last_nonexec_reason = reason
                if (not self.internal_rejudge_enable
                        or (action_limit > 0 and self.internal_rejudge_attempt >= action_limit)):
                    self.post_action_rejudge_requested = False
                    self.internal_rejudge_requested = False
                    self.internal_rejudge_origin = None
                    self.state = "REJUDGE_LIMIT"
                    return {
                        "kind": "rejudge_limit", "action": action, "state": self.state,
                        "scheduled": False, "limit": action_limit,
                    }
                self.internal_rejudge_attempt += 1
                self.post_action_rejudge_requested = False
                self.internal_rejudge_requested = True
                self.internal_rejudge_origin = "INTERNAL"
                self.rejudge_not_before = float(now) + self.internal_rejudge_delay_s
                self.state = "INTERNAL_REJUDGING"
                return {
                    "kind": "internal_rejudge",
                    "action": action,
                    "state": self.state,
                    "scheduled": True,
                    "attempt": self.internal_rejudge_attempt,
                    "limit": action_limit,
                }
            self.post_action_rejudge_requested = False
            self.internal_rejudge_requested = False
            self.internal_rejudge_origin = None
            self.state = "WAITING_ENTER"
            return {"kind": "executable", "action": action, "state": self.state, "scheduled": False}

    def claim_scheduled_rejudge(self, now: float, motion_busy: bool,
                                yolo_busy: bool, pending_exists: bool) -> Optional[Dict[str, Any]]:
        with self._lock:
            if (not self.armed or bool(motion_busy) or bool(yolo_busy) or bool(pending_exists)
                    or float(now) < float(self.rejudge_not_before)):
                return None
            if self.post_action_rejudge_requested:
                self.post_action_rejudge_requested = False
                self.state = "POST_ACTION_REJUDGING"
                return {"origin": "POST_ACTION", "attempt": 0, "epoch": int(self.epoch)}
            if self.internal_rejudge_requested:
                self.internal_rejudge_requested = False
                self.state = "JUDGING"
                return {
                    "origin": str(self.internal_rejudge_origin or "INTERNAL"),
                    "attempt": int(self.internal_rejudge_attempt),
                    "epoch": int(self.epoch),
                }
            return None

    def restore_claim(self, claim: Optional[Dict[str, Any]]) -> None:
        with self._lock:
            if (not isinstance(claim, dict) or not self.armed
                    or int(claim.get("epoch", -1)) != int(self.epoch)):
                return
            origin = str(claim.get("origin", ""))
            if origin == "POST_ACTION":
                self.post_action_rejudge_requested = True
                self.state = "POST_ACTION_STANDBY"
            else:
                self.internal_rejudge_requested = True
                self.internal_rejudge_origin = origin or "INTERNAL"
                self.state = "INTERNAL_REJUDGING"

    def fail(self, reason: str, fatal: bool = False) -> None:
        with self._lock:
            # An error/timeout is a decision-generation boundary even when the
            # cycle remains armed for manual-X recovery.  Late worker results
            # from the failed generation must not republish WAITING_ENTER.
            self.epoch += 1
            self.post_action_rejudge_requested = False
            self.internal_rejudge_requested = False
            self.internal_rejudge_origin = None
            self.last_error = str(reason)
            self.state = "ERROR"
            if fatal:
                self.armed = False
                self.internal_rejudge_attempt = 0
                self.last_nonexec_action = None
                self.last_nonexec_reason = ""

    def timeout(self, reason: str) -> None:
        self.fail(reason, fatal=False)

    def fail_if_current(self, expected_epoch: int, reason: str,
                        fatal: bool = False, publisher=None) -> bool:
        with self._lock:
            if not self.armed or int(expected_epoch) != int(self.epoch):
                return False
            self.epoch += 1
            self.post_action_rejudge_requested = False
            self.internal_rejudge_requested = False
            self.internal_rejudge_origin = None
            self.last_error = str(reason)
            self.state = "ERROR"
            if fatal:
                self.armed = False
                self.internal_rejudge_attempt = 0
                self.last_nonexec_action = None
                self.last_nonexec_reason = ""
            if publisher is not None:
                publisher()
            return True

    def disarm(self, reason: str, terminal_state: str = "IDLE") -> None:
        with self._lock:
            self._disarm_locked(reason, terminal_state)

    def _disarm_locked(self, reason: str, terminal_state: str) -> None:
        self.epoch += 1
        self.armed = False
        self.post_action_rejudge_requested = False
        self.internal_rejudge_requested = False
        self.internal_rejudge_origin = None
        self.rejudge_not_before = 0.0
        self.last_error = str(reason)
        self.internal_rejudge_attempt = 0
        self.last_nonexec_action = None
        self.last_nonexec_reason = ""
        self.state = str(terminal_state)

    def current_epoch(self) -> int:
        with self._lock:
            return int(self.epoch)

    def is_current(self, expected_epoch: int) -> bool:
        with self._lock:
            return bool(self.armed and int(expected_epoch) == int(self.epoch))

    def commit_pending_if_current(self, expected_epoch: int, publisher) -> bool:
        """Run the external pending assignment atomically against reset/disarm."""
        with self._lock:
            if (not self.armed or int(expected_epoch) != int(self.epoch)
                    or self.state != "WAITING_ENTER"):
                return False
            publisher()
            return True

    def mutate_if_current(self, expected_epoch: int, publisher) -> bool:
        """Publish non-pending UI/cache state only for the live generation."""
        with self._lock:
            if not self.armed or int(expected_epoch) != int(self.epoch):
                return False
            publisher()
            return True

    def disarm_if_current(self, expected_epoch: int, reason: str,
                          terminal_state: str, publisher=None) -> bool:
        with self._lock:
            if not self.armed or int(expected_epoch) != int(self.epoch):
                return False
            self._disarm_locked(reason, terminal_state)
            if publisher is not None:
                publisher()
            return True

    def hold_for_human_confirmation(self, expected_epoch: int) -> bool:
        """Keep a terminal FINISH proposal in WAITING_ENTER for dataset labeling.

        This does not authorize a robot motion. Enter accepts FINISH, while the
        VLA control panel can replace it with another safely resolved macro action.
        """
        with self._lock:
            if not self.armed or int(expected_epoch) != int(self.epoch):
                return False
            self.post_action_rejudge_requested = False
            self.internal_rejudge_requested = False
            self.internal_rejudge_origin = None
            self.state = "WAITING_ENTER"
            return True

    def snapshot_state(self) -> Dict[str, Any]:
        with self._lock:
            return copy.deepcopy({k: v for k, v in self.__dict__.items() if k != "_lock"})

    def restore_state_if_current(self, snapshot: Dict[str, Any],
                                 expected_epoch: int, publisher=None) -> bool:
        """Rollback a failed worker launch without undoing a concurrent reset."""
        with self._lock:
            if not self.armed or int(expected_epoch) != int(self.epoch):
                return False
            if publisher is not None:
                publisher()
            for key in [k for k in self.__dict__ if k != "_lock"]:
                del self.__dict__[key]
            self.__dict__.update(copy.deepcopy(dict(snapshot)))
            return True


class A140LatencyTracker:
    """Thread-safe monotonic timestamps for one AUTO-X decision gap."""

    _JUDGMENT_STAGE_PAIRS = {
        "burst_s": ("snapshot_request", "burst_complete"),
        "fresh_burst_s": ("burst_start", "burst_complete"),
        "segmentation_s": ("inference_start", "segmentation_complete"),
        "pose_s": ("segmentation_complete", "pose_complete"),
        "rotate_pair_plan_s": ("rotate_pair_plan_start", "rotate_pair_plan_end"),
        "inference_s": ("inference_start", "inference_complete"),
        "heatmap_cca_s": ("heatmap_cca_start", "heatmap_cca_complete"),
        "pose_symmetry_s": ("pose_symmetry_start", "pose_symmetry_end"),
        "micro_unfold_s": ("micro_unfold_start", "micro_unfold_end"),
        "long_pull_prefreeze_s": ("long_pull_prefreeze_start", "long_pull_prefreeze_end"),
        "vla_save_enqueue_s": ("vla_save_enqueue_start", "vla_save_enqueue_end"),
        "planner_s": ("planner_start", "planner_end"),
    }

    def __init__(self, clock=None):
        self._clock = clock if clock is not None else time.monotonic
        self._lock = threading.RLock()
        self._data: Dict[str, Any] = {}

    def begin(self, cycle: int, action: str, entry_mark: str) -> None:
        with self._lock:
            self._data = {"cycle": int(cycle), "action": str(action)}
            self._data[str(entry_mark)] = float(self._clock())

    def active(self) -> bool:
        with self._lock:
            return bool(self._data)

    def mark(self, name: str, **meta) -> None:
        with self._lock:
            if not self._data:
                return
            key = str(name)
            now = float(self._clock())
            if key == "snapshot_request":
                if "snapshot_request" in self._data:
                    self._archive_judgment_locked()
                self._data.setdefault("first_snapshot_request", now)
            self._data[key] = now
            for key, value in meta.items():
                self._data[str(key)] = value

    def mark_once(self, name: str, **meta) -> None:
        with self._lock:
            if not self._data:
                return
            key = str(name)
            if key not in self._data:
                self._data[key] = float(self._clock())
            for meta_key, value in meta.items():
                self._data[str(meta_key)] = value

    @staticmethod
    def _duration(data: Dict[str, Any], start: str, end: str) -> Optional[float]:
        try:
            value = float(data[end]) - float(data[start])
            return value if value >= 0.0 else None
        except Exception:
            return None

    @staticmethod
    def _fmt(value: Optional[float]) -> str:
        return "NA" if value is None else f"{float(value):.3f}"

    def _archive_judgment_locked(self) -> None:
        if "snapshot_request" not in self._data:
            return
        span: Dict[str, Any] = {}
        markers = set()
        for field_name, (start, end) in self._JUDGMENT_STAGE_PAIRS.items():
            span[field_name] = self._duration(self._data, start, end)
            markers.update((start, end))
        # Diagnostic-only metadata for integrated-vs-standalone camera latency.
        # A completed burst is the exact fresh-frame acquisition window used by
        # the logical judgment; preserving its frame count lets the log expose
        # the effective per-frame arrival interval without changing capture.
        if "burst_complete" in self._data:
            try:
                burst_frames = int(self._data.get("burst_frame_count", 0) or 0)
            except Exception:
                burst_frames = 0
            if burst_frames > 0:
                span["burst_frames"] = burst_frames
        self._data.setdefault("_judgment_spans", []).append(span)
        for marker in markers:
            self._data.pop(marker, None)
        self._data.pop("burst_frame_count", None)

    @staticmethod
    def _sum_judgment_stage(data: Dict[str, Any], field_name: str) -> Optional[float]:
        values = []
        for span in list(data.get("_judgment_spans", []) or []):
            if isinstance(span, dict) and span.get(field_name) is not None:
                values.append(float(span[field_name]))
        return float(sum(values)) if values else None

    @staticmethod
    def _sum_judgment_count(data: Dict[str, Any], field_name: str) -> int:
        total = 0
        for span in list(data.get("_judgment_spans", []) or []):
            if not isinstance(span, dict):
                continue
            try:
                value = int(span.get(field_name, 0) or 0)
            except Exception:
                value = 0
            if value > 0:
                total += value
        return int(total)

    def finish_line(self, outcome_action: str) -> Optional[str]:
        with self._lock:
            if not self._data:
                return None
            self._archive_judgment_locked()
            self._data["decision_displayed"] = float(self._clock())
            data = copy.deepcopy(self._data)
            self._data = {}
        fields = {
            "worker_wait_s": self._duration(data, "enter_input", "pending_worker_start"),
            "motion_s": self._duration(data, "physical_action_start", "physical_action_end"),
            "release_to_vertical_clear_s": self._duration(data, "release_end", "vertical_clear_end"),
            "vertical_clear_to_release_s": self._duration(data, "vertical_clear_end", "release_end"),
            "standby_s": self._duration(data, "standby_command_start", "standby_command_end"),
            "post_action_snapshot_delay_s": self._duration(data, "physical_action_end", "first_snapshot_request"),
            "burst_s": self._sum_judgment_stage(data, "burst_s"),
            "segmentation_s": self._sum_judgment_stage(data, "segmentation_s"),
            "pose_s": self._sum_judgment_stage(data, "pose_s"),
            "inference_s": self._sum_judgment_stage(data, "inference_s"),
            "heatmap_cca_s": self._sum_judgment_stage(data, "heatmap_cca_s"),
            "rotate_pair_plan_s": self._sum_judgment_stage(data, "rotate_pair_plan_s"),
            "pose_symmetry_s": self._sum_judgment_stage(data, "pose_symmetry_s"),
            "micro_unfold_s": self._sum_judgment_stage(data, "micro_unfold_s"),
            "long_pull_prefreeze_s": self._sum_judgment_stage(data, "long_pull_prefreeze_s"),
            "vla_save_enqueue_s": self._sum_judgment_stage(data, "vla_save_enqueue_s"),
            "planner_s": self._sum_judgment_stage(data, "planner_s"),
            "post_action_to_pending_s": self._duration(data, "physical_action_end", "decision_displayed"),
            "total_enter_to_pending_s": self._duration(data, "enter_input", "decision_displayed"),
        }
        safe_outcome = str(outcome_action).replace(" ", "_")
        action_name = str(data.get("action", "NA")).replace(" ", "_")
        judgment_count = len(list(data.get("_judgment_spans", []) or []))
        parts = [
            "[A140-LATENCY]",
            f"cycle={int(data.get('cycle', 0))}",
            f"action={action_name}",
            f"outcome={safe_outcome}",
            f"judgments={judgment_count}",
        ]
        parts.extend(f"{name}={self._fmt(value)}" for name, value in fields.items())
        a140_line = " ".join(parts)

        # Human-readable latency summary for diagnosing the gap between one
        # completed garment action and the next selected action.  This is log
        # only: it reuses timestamps already collected by A140 and does not add
        # sleeps, captures, inference, planner calls, or synchronization.
        burst_s = fields.get("burst_s")
        fresh_burst_s = self._sum_judgment_stage(data, "fresh_burst_s")
        burst_frames = self._sum_judgment_count(data, "burst_frames")
        pre_burst_wait_s = None
        if burst_s is not None and fresh_burst_s is not None:
            pre_burst_wait_s = max(0.0, float(burst_s) - float(fresh_burst_s))
        effective_frame_interval_s = None
        effective_fps = None
        # burst_start is marked on the first captured frame, so N captured frames
        # contain N-1 inter-frame intervals between burst_start and burst_complete.
        if fresh_burst_s is not None and burst_frames > 1 and float(fresh_burst_s) > 0.0:
            effective_frame_interval_s = float(fresh_burst_s) / float(burst_frames - 1)
            effective_fps = float(burst_frames - 1) / float(fresh_burst_s)
        upper_parts = [
            "[UPPER-LATENCY]",
            f"cycle={int(data.get('cycle', 0))}",
            f"prev_action={action_name}",
            f"next_outcome={safe_outcome}",
            f"judgments={judgment_count}",
            f"action_end_to_snapshot_request_s={self._fmt(fields.get('post_action_snapshot_delay_s'))}",
            f"snapshot_to_burst_complete_s={self._fmt(burst_s)}",
            f"pre_burst_wait_s={self._fmt(pre_burst_wait_s)}",
            f"fresh_burst_s={self._fmt(fresh_burst_s)}",
            f"fresh_frames={burst_frames if burst_frames > 0 else 'NA'}",
            f"effective_frame_interval_s={self._fmt(effective_frame_interval_s)}",
            f"effective_fps={self._fmt(effective_fps)}",
            f"segmentation_s={self._fmt(fields.get('segmentation_s'))}",
            f"pose_s={self._fmt(fields.get('pose_s'))}",
            f"inference_s={self._fmt(fields.get('inference_s'))}",
            f"heatmap_cca_s={self._fmt(fields.get('heatmap_cca_s'))}",
            f"micro_unfold_s={self._fmt(fields.get('micro_unfold_s'))}",
            f"planner_s={self._fmt(fields.get('planner_s'))}",
            f"action_end_to_next_decision_s={self._fmt(fields.get('post_action_to_pending_s'))}",
            f"motion_s={self._fmt(fields.get('motion_s'))}",
        ]
        return a140_line + "\n" + " ".join(upper_parts)


class _AutoXTeeStream:
    def __init__(self, logger: "AutoXDebugLogger", stream_name: str, original_stream):
        self.logger = logger
        self.stream_name = str(stream_name)
        self.original_stream = original_stream
        self.encoding = getattr(original_stream, "encoding", "utf-8")
        self.errors = getattr(original_stream, "errors", "replace")

    def write(self, data):
        self.logger.write(self.stream_name, data)
        return len(data) if data is not None else 0

    def flush(self):
        self.logger.flush(self.stream_name)

    def isatty(self):
        return bool(getattr(self.original_stream, "isatty", lambda: False)())

    def fileno(self):
        return self.original_stream.fileno()

    def __getattr__(self, name):
        return getattr(self.original_stream, name)


class AutoXDebugLogger:
    """Tee stdout/stderr into one text file for one garment AUTO-X cycle.

    B50-v4 policy:
      - First X opens one cycle log.
      - Later X judgments and ENTER/SPACE executions append to the same file.
      - READY, STOP, manual A-reset, or program exit closes the cycle log.
    """

    def __init__(self, base_dir: str = "auto_x_logs", enabled: bool = True):
        self.enabled = bool(enabled)
        self.base_dir = os.path.abspath(os.path.expanduser(str(base_dir or "auto_x_logs")))
        self._orig_stdout = sys.stdout
        self._orig_stderr = sys.stderr
        self._installed = False
        self._lock = threading.RLock()
        self._file = None
        self._path = None
        self._session_idx = 0
        self._active = False
        self._decision_idx = 0
        self._action_idx = 0
        self._cycle_started_at = None
        self._pending_stop_reason = None

    def install(self):
        if not self.enabled or self._installed:
            return
        sys.stdout = _AutoXTeeStream(self, "stdout", self._orig_stdout)
        sys.stderr = _AutoXTeeStream(self, "stderr", self._orig_stderr)
        self._installed = True

    def clear_old_logs(self):
        """Compatibility name retained; VLA collection is append-only and never deletes old logs."""
        if not self.enabled:
            return
        os.makedirs(self.base_dir, exist_ok=True)
        _vla_fix_created_owner(self.base_dir)
        try:
            existing = sum(1 for name in os.listdir(self.base_dir)
                           if os.path.isfile(os.path.join(self.base_dir, name)) and name.lower().endswith(".txt"))
        except Exception:
            existing = -1
        print(f"[AUTO-X-LOG] append-only log directory ready: {self.base_dir} | retained_old_txt={existing}")

    def is_active(self) -> bool:
        with self._lock:
            return bool(self._file is not None and self._active)

    def current_path(self):
        with self._lock:
            return self._path

    @_pipeline_v2.timed('text_session_start', 'io')
    def start_session(self, label: str = "x-auto-judge-only", reason: str = "key X"):
        """Start a garment cycle or append a new X decision to the active cycle."""
        if not self.enabled:
            return None
        with self._lock:
            if self._file is None:
                os.makedirs(self.base_dir, exist_ok=True)
                _vla_fix_created_owner(self.base_dir)
                self._session_idx += 1
                self._decision_idx = 0
                self._action_idx = 0
                self._pending_stop_reason = None
                self._cycle_started_at = float(time.time())
                now = time.time()
                ts = time.strftime("%Y%m%d_%H%M%S", time.localtime(now)) + f"_{int((now % 1.0) * 1000):03d}"
                safe_label = "".join(ch if ch.isalnum() or ch in ("-", "_") else "_" for ch in str(label))[:80]
                filename = f"auto_x_cycle_{self._session_idx:03d}_{ts}_{safe_label}.txt"
                self._path = os.path.join(self.base_dir, filename)
                suffix = 1
                while os.path.exists(self._path):
                    self._path = os.path.join(self.base_dir, f"auto_x_cycle_{self._session_idx:03d}_{ts}_{safe_label}_{suffix:02d}.txt")
                    suffix += 1
                self._file = open(self._path, "x", encoding="utf-8", buffering=1)
                _vla_fix_created_owner(self._path)
                self._active = True
                print("\n========== AUTO-X GARMENT CYCLE LOG START ==========")
                print(f"[AUTO-X-LOG] file={self._path}")
                print(f"[AUTO-X-LOG] label={label} reason={reason} started_at={time.strftime('%Y-%m-%d %H:%M:%S')}")
                print("===================================================")
            self._decision_idx += 1
            print(f"\n========== AUTO-X CYCLE DECISION {self._decision_idx:02d} ==========")
            print(f"[AUTO-X-LOG] decision={self._decision_idx} reason={reason} at={time.strftime('%Y-%m-%d %H:%M:%S')}")
            print("===================================================\n")
            return self._path

    def mark_action(self, action: str, reason: str = ""):
        if not self.enabled:
            return
        with self._lock:
            if self._file is None:
                return
            self._action_idx += 1
            print(f"\n========== AUTO-X CYCLE ACTION {self._action_idx:02d} ==========")
            print(f"[AUTO-X-LOG] action={action} at={time.strftime('%Y-%m-%d %H:%M:%S')}")
            if reason:
                print(f"[AUTO-X-LOG] action_reason={reason}")
            print("=================================================\n")

    def request_stop(self, reason: str):
        """Close after the current X judgment worker prints its final line."""
        if not self.enabled:
            return
        with self._lock:
            if self._file is not None:
                self._pending_stop_reason = str(reason or "AUTO-X cycle finished")

    def consume_stop_request(self):
        with self._lock:
            reason = self._pending_stop_reason
            self._pending_stop_reason = None
            return reason

    @_pipeline_v2.timed('text_session_stop', 'io')
    def stop_session(self, reason: str = "session finished"):
        if not self.enabled:
            return
        with self._lock:
            if self._file is None:
                return
            try:
                elapsed = None if self._cycle_started_at is None else max(0.0, float(time.time()) - float(self._cycle_started_at))
                print("\n========== AUTO-X GARMENT CYCLE LOG END ==========")
                print(f"[AUTO-X-LOG] reason={reason} ended_at={time.strftime('%Y-%m-%d %H:%M:%S')}")
                print(f"[AUTO-X-LOG] decisions={self._decision_idx} actions={self._action_idx} elapsed_s={elapsed if elapsed is not None else 'NA'}")
                print(f"[AUTO-X-LOG] saved={self._path}")
                print("=================================================\n")
            finally:
                try:
                    self._file.flush()
                    self._file.close()
                except Exception:
                    pass
                self._file = None
                self._path = None
                self._active = False
                self._decision_idx = 0
                self._action_idx = 0
                self._cycle_started_at = None
                self._pending_stop_reason = None

    def close(self):
        self.stop_session("program exit")
        if self._installed:
            sys.stdout = self._orig_stdout
            sys.stderr = self._orig_stderr
            self._installed = False

    @_pipeline_v2.timed('text_write_flush', 'io')
    def write(self, stream_name: str, data):
        if data is None:
            return
        text = str(data)
        original = self._orig_stderr if stream_name == "stderr" else self._orig_stdout
        with self._lock:
            try:
                original.write(text)
            except Exception:
                pass
            try:
                _pipeline_v2.io_call('text_flush', original.flush)
            except Exception:
                pass
            if self.enabled and self._file is not None:
                try:
                    if stream_name == "stderr":
                        self._file.write("[STDERR] ")
                    self._file.write(text)
                    _pipeline_v2.io_call('text_flush', self._file.flush)
                except Exception:
                    pass

    @_pipeline_v2.timed('text_flush', 'io')
    def flush(self, stream_name: str = "stdout"):
        original = self._orig_stderr if stream_name == "stderr" else self._orig_stdout
        try:
            _pipeline_v2.io_call('text_flush', original.flush)
        except Exception:
            pass
        with self._lock:
            if self._file is not None:
                try:
                    _pipeline_v2.io_call('text_flush', self._file.flush)
                except Exception:
                    pass


class _AutoXDebugIOWriter:
    """One FIFO for AUTO-X bundles/patches; reuse the existing debug producer lock."""

    def __init__(self, write_job, submit_lock):
        self.write_job, self.submit_lock = write_job, submit_lock
        # ponytail: two waiting image bundles; backpressure drains before sync fallback.
        self.jobs = queue.Queue(maxsize=2)
        self.closed = False
        self.failures = 0
        self.thread = threading.Thread(target=self._run, name="auto-x-debug-io", daemon=True)
        self.thread.start()

    def _execute(self, job):
        try:
            if self.write_job(job) is False:
                raise OSError("partial debug save; see image/patch warning")
        except Exception as exc:
            self.failures += 1
            print(f"[AUTO-X-DEBUG-IO-ERROR] path={job.get('decision_dir') or job.get('path')} error={exc!r}")

    def _run(self):
        _pipeline_v2.thread_role("background")  # keep daemon I/O out of critical-path debug_io_s
        while True:
            try:
                job = self.jobs.get(timeout=0.10)
            except queue.Empty:
                if self.closed:
                    return
                continue
            try:
                self._execute(job)
            finally:
                del job  # release detached NumPy payloads before waiting for the next job
                self.jobs.task_done()

    def submit(self, job):
        with self.submit_lock:
            if self.closed:
                raise RuntimeError("debug writer closed; job not accepted")
            try:
                self.jobs.put_nowait(job)
            except queue.Full:
                print("[AUTO-X-DEBUG-IO-WARN] queue full; drain older jobs before synchronous fallback")
                if not self.flush():
                    raise TimeoutError("debug queue full; job NOT accepted after drain timeout")
                self._execute(job)

    def flush(self, timeout=20.0):
        with self.jobs.all_tasks_done:
            drained = self.jobs.all_tasks_done.wait_for(lambda: self.jobs.unfinished_tasks == 0, timeout=timeout)
            pending = self.jobs.unfinished_tasks
        if not drained:
            print(f"[AUTO-X-DEBUG-IO-ERROR] drain timeout pending={pending}; records NOT confirmed complete")
        return drained

    def close(self, timeout=20.0):
        deadline = time.monotonic() + max(0.0, timeout)
        if not self.submit_lock.acquire(timeout=max(0.0, deadline - time.monotonic())):
            # A producer may still be doing synchronous fallback I/O; it cannot be cancelled.
            print("[AUTO-X-DEBUG-IO-ERROR] close lock timeout; records NOT confirmed complete; close must be retried")
            return False
        try:
            self.closed = True  # accepted jobs keep draining through abort/recovery/close.
            drained = self.flush(max(0.0, deadline - time.monotonic()))
            if drained:
                self.thread.join(timeout=max(0.0, deadline - time.monotonic()))
                if self.thread.is_alive():
                    print("[AUTO-X-DEBUG-IO-ERROR] close exit timeout; writer still running")
            if self.failures:
                print(f"[AUTO-X-DEBUG-IO-ERROR] shutdown write_failures={self.failures}")
            return drained and not self.thread.is_alive() and self.failures == 0
        finally:
            self.submit_lock.release()


# A148: CCA READY profile values may be overridden by one validated JSON file.
# Measurement equations, component classification, robot motion, and every non-CCA
# setting remain code-owned and cannot be changed by this patch mechanism.
CCA_THRESHOLD_PATCH_DEFAULT_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "cca_threshold_patch.json")
CCA_THRESHOLD_PATCH_SCHEMA_VERSION = 1
CCA_THRESHOLD_PATCH_KEYS = (
    "auto_x_ready_cca_profile_max_component_area_ratio",
    "auto_x_ready_cca_profile_clean_active_max",
    "auto_x_ready_cca_profile_clean_strong_max",
    "auto_x_ready_cca_profile_clean_medium_max",
    "auto_x_ready_cca_profile_residual_active_max",
    "auto_x_ready_cca_profile_residual_strong_max",
    "auto_x_ready_cca_profile_residual_medium_max",
    "auto_x_ready_cca_profile_very_low_active_max",
    "auto_x_ready_cca_profile_very_low_strong_max",
    "auto_x_ready_cca_profile_very_low_medium_max",
)
CCA_THRESHOLD_PATCH_RATIO_KEYS = frozenset({
    "auto_x_ready_cca_profile_max_component_area_ratio",
    "auto_x_ready_cca_profile_clean_active_max",
    "auto_x_ready_cca_profile_residual_active_max",
    "auto_x_ready_cca_profile_very_low_active_max",
})
CCA_THRESHOLD_PATCH_COUNT_KEYS = frozenset(set(CCA_THRESHOLD_PATCH_KEYS) - set(CCA_THRESHOLD_PATCH_RATIO_KEYS))
CCA_THRESHOLD_PATCH_CLI_FLAGS = {
    "auto_x_ready_cca_profile_max_component_area_ratio": "--auto-x-ready-cca-profile-max-component-area-ratio",
    "auto_x_ready_cca_profile_clean_active_max": "--auto-x-ready-cca-profile-clean-active-max",
    "auto_x_ready_cca_profile_clean_strong_max": "--auto-x-ready-cca-profile-clean-strong-max",
    "auto_x_ready_cca_profile_clean_medium_max": "--auto-x-ready-cca-profile-clean-medium-max",
    "auto_x_ready_cca_profile_residual_active_max": "--auto-x-ready-cca-profile-residual-active-max",
    "auto_x_ready_cca_profile_residual_strong_max": "--auto-x-ready-cca-profile-residual-strong-max",
    "auto_x_ready_cca_profile_residual_medium_max": "--auto-x-ready-cca-profile-residual-medium-max",
    "auto_x_ready_cca_profile_very_low_active_max": "--auto-x-ready-cca-profile-very-low-active-max",
    "auto_x_ready_cca_profile_very_low_strong_max": "--auto-x-ready-cca-profile-very-low-strong-max",
    "auto_x_ready_cca_profile_very_low_medium_max": "--auto-x-ready-cca-profile-very-low-medium-max",
}


def _a148_patch_cli_flag_present(argv: List[str], flag: str) -> bool:
    return any(str(token) == str(flag) or str(token).startswith(str(flag) + "=") for token in argv)


def _a148_validate_cca_patch_values(values: Dict[str, Any], built_in: Dict[str, Any]) -> Dict[str, Any]:
    if not isinstance(values, dict):
        raise ValueError("'values' must be a JSON object")
    unknown = sorted(set(values) - set(CCA_THRESHOLD_PATCH_KEYS))
    if unknown:
        raise ValueError("unsupported CCA patch key(s): " + ", ".join(unknown))

    effective = dict(built_in)
    for key, raw in values.items():
        if key in CCA_THRESHOLD_PATCH_RATIO_KEYS:
            if isinstance(raw, bool) or not isinstance(raw, (int, float)):
                raise ValueError(f"{key} must be a finite number in [0, 1]")
            value = float(raw)
            if not math.isfinite(value) or value < 0.0 or value > 1.0:
                raise ValueError(f"{key} must be a finite number in [0, 1]")
            effective[key] = value
        elif key in CCA_THRESHOLD_PATCH_COUNT_KEYS:
            if isinstance(raw, bool) or not isinstance(raw, int) or int(raw) < 0:
                raise ValueError(f"{key} must be a non-negative integer")
            effective[key] = int(raw)

    very_low = float(effective["auto_x_ready_cca_profile_very_low_active_max"])
    residual = float(effective["auto_x_ready_cca_profile_residual_active_max"])
    clean = float(effective["auto_x_ready_cca_profile_clean_active_max"])
    if not (very_low <= residual <= clean):
        raise ValueError(
            "active thresholds must satisfy very_low_active_max <= residual_active_max <= clean_active_max"
        )
    return effective


def _a148_prepare_cca_threshold_patch(settings: Dict[str, Any], enabled: bool,
                                      patch_path: str) -> Dict[str, Any]:
    built_in = {key: copy.deepcopy(settings[key]) for key in CCA_THRESHOLD_PATCH_KEYS}
    resolved_path = os.path.abspath(os.path.expanduser(str(patch_path or CCA_THRESHOLD_PATCH_DEFAULT_PATH)))
    state: Dict[str, Any] = {
        "enabled": bool(enabled),
        "source": "built_in",
        "path": resolved_path,
        "file_exists": bool(os.path.isfile(resolved_path)),
        "patch_id": None,
        "measurement_version": None,
        "description": "",
        "schema_version": None,
        "declared_values": {},
        "built_in_values": built_in,
        "effective_values": dict(built_in),
        "cli_overrides": [],
    }
    if not bool(enabled):
        state["reason"] = "disabled_by_cli"
        return state
    if not os.path.isfile(resolved_path):
        state["reason"] = "file_not_found"
        return state

    try:
        with open(resolved_path, "r", encoding="utf-8") as f:
            payload = json.load(f)
    except Exception as e:
        raise ValueError(f"failed to read JSON patch {resolved_path}: {e}") from e
    if not isinstance(payload, dict):
        raise ValueError("CCA threshold patch root must be a JSON object")
    schema_version = payload.get("schema_version", None)
    if isinstance(schema_version, bool) or not isinstance(schema_version, int):
        raise ValueError("schema_version must be integer 1")
    if int(schema_version) != int(CCA_THRESHOLD_PATCH_SCHEMA_VERSION):
        raise ValueError(
            f"unsupported schema_version={schema_version}; expected {CCA_THRESHOLD_PATCH_SCHEMA_VERSION}"
        )
    values = payload.get("values", {})
    effective = _a148_validate_cca_patch_values(values, built_in)
    for key, value in effective.items():
        settings[key] = copy.deepcopy(value)

    state.update({
        "source": "patch",
        "reason": "loaded",
        "patch_id": str(payload.get("patch_id", "UNNAMED_PATCH")),
        "measurement_version": str(payload.get("measurement_version", "UNSPECIFIED")),
        "description": str(payload.get("description", "")),
        "schema_version": int(schema_version),
        "declared_values": copy.deepcopy(values),
        "effective_values": copy.deepcopy(effective),
    })
    return state


def _a148_finalize_cca_threshold_patch_state(state: Dict[str, Any], args,
                                             argv: List[str]) -> Dict[str, Any]:
    out = copy.deepcopy(state)
    effective = {}
    cli_overrides = []
    for key in CCA_THRESHOLD_PATCH_KEYS:
        effective[key] = copy.deepcopy(getattr(args, key))
        flag = CCA_THRESHOLD_PATCH_CLI_FLAGS[key]
        if _a148_patch_cli_flag_present(argv, flag):
            cli_overrides.append(key)
    # Validate the final merged profile too, so an explicit CLI override cannot
    # create an incoherent or negative profile after a valid JSON was loaded.
    effective = _a148_validate_cca_patch_values(effective, out.get("built_in_values", effective))
    out["effective_values"] = effective
    out["cli_overrides"] = cli_overrides
    if cli_overrides:
        out["source"] = "patch+cli" if out.get("source") == "patch" else "built_in+cli"
    return out


def _a148_log_cca_threshold_patch_state(state: Dict[str, Any]) -> None:
    source = str(state.get("source", "built_in"))
    path = str(state.get("path", CCA_THRESHOLD_PATCH_DEFAULT_PATH))
    reason = str(state.get("reason", ""))
    print("\n========== A148 CCA THRESHOLD PROFILE ==========")
    print(f"[CCA-PATCH] source={source} enabled={bool(state.get('enabled', True))}")
    print(f"[CCA-PATCH] file={path}")
    if source.startswith("patch"):
        print(f"[CCA-PATCH] patch_id={state.get('patch_id')}")
        print(f"[CCA-PATCH] measurement_version={state.get('measurement_version')}")
        if state.get("description"):
            print(f"[CCA-PATCH] description={state.get('description')}")
    else:
        print(f"[CCA-PATCH] using built-in A147 defaults reason={reason or 'not_loaded'}")
    if state.get("cli_overrides"):
        print("[CCA-PATCH] CLI overrides=" + ",".join(state["cli_overrides"]))

    built_in = state.get("built_in_values", {})
    effective = state.get("effective_values", {})
    for key in CCA_THRESHOLD_PATCH_KEYS:
        old = built_in.get(key)
        new = effective.get(key)
        marker = "CHANGED" if old != new else "KEEP"
        print(f"[CCA-PATCH] {marker} {key}: {old} -> {new}")
    print("[CCA-PATCH] validated; affects CCA READY profile and Late blocker interpretation only")
    print("================================================\n")


