    parser.add_argument("--smart-reposition-suppress-non-smart-overlay", dest="smart_reposition_suppress_non_smart_overlay", action="store_true",
                        default=USER_SETTINGS.get("smart_reposition_suppress_non_smart_overlay", True),
                        help="While key 4 AUTO CENTER is running, hide stale SELECT/SPREAD/center/press overlays and show only the SMART REPOSITION pick/drag overlay.")
    parser.add_argument("--no-smart-reposition-suppress-non-smart-overlay", dest="smart_reposition_suppress_non_smart_overlay", action="store_false",
                        help="Do not hide non-smart overlays during key 4 AUTO CENTER.")
