    parser.add_argument("--lab-empty-veto-require-baseline", dest="lab_empty_veto_require_baseline", action="store_true",
                        default=USER_SETTINGS.get("lab_empty_veto_require_baseline", False),
                        help="When Lab veto is enabled, reject garment candidates until E-key empty baseline exists.")
    parser.add_argument("--no-lab-empty-veto-require-baseline", dest="lab_empty_veto_require_baseline", action="store_false")
