    parser.add_argument("--no-auto-pick", dest="auto_pick", action="store_false")
    parser.add_argument("--auto-pick-samples", type=int, default=6)
    parser.add_argument("--auto-pick-min-samples", type=int, default=4)

    # Snapshot-grasp mode:
    # Keep the arms at standby, wait until the view is still, freeze one image,
    # and run YOLO on that frozen image. This prevents the arms from blocking
    # the clothing while the grasp point is being selected.
    parser.add_argument("--live-grasp", action="store_true", default=USER_SETTINGS["live_grasp"],
                        help="Disable snapshot-grasp mode and run YOLO continuously on live frames.")
    parser.add_argument("--settle-seconds", type=float, default=USER_SETTINGS["settle_seconds"],
                        help="Seconds the view must remain still before one snapshot is captured. WAITOPT-V1 default is 0.30s.")
    parser.add_argument("--settle-motion-threshold", type=float, default=USER_SETTINGS["settle_motion_threshold"],
                        help="Mean pixel-difference threshold for stillness detection. Smaller is stricter.")
    parser.add_argument("--settle-min-frames", type=int, default=USER_SETTINGS["settle_min_frames"],
                        help="Minimum low-motion frames before snapshot capture.")
    parser.add_argument("--cloth-trigger", dest="cloth_trigger", action="store_true", default=USER_SETTINGS["cloth_trigger"],
                        help="Wait for cloth-placement change before starting the stillness timer.")
    parser.add_argument("--no-cloth-trigger", dest="cloth_trigger", action="store_false",
                        help="Capture after stillness only, without checking that cloth was newly placed.")
    parser.add_argument("--cloth-change-threshold", type=float, default=USER_SETTINGS["cloth_change_threshold"],
                        help="Mean pixel difference from empty-board baseline used to detect cloth placement.")
    parser.add_argument("--cloth-baseline-frames", type=int, default=USER_SETTINGS["cloth_baseline_frames"],
                        help="Number of initial frames used for empty-board baseline after Homography lock.")
    parser.add_argument("--async-motion", dest="async_motion", action="store_true", default=USER_SETTINGS["async_motion"],
                        help="Run robot pick in a background thread so the OpenCV window keeps updating.")
    parser.add_argument("--no-async-motion", dest="async_motion", action="store_false",
                        help="Run robot pick in the main loop, old blocking behavior.")
    parser.add_argument("--freeze-snapshot-display", dest="freeze_snapshot_display", action="store_true",
                        default=USER_SETTINGS["freeze_snapshot_display"],
                        help="Show frozen YOLO snapshot after inference. Default OFF: keep live camera view.")
    parser.add_argument("--no-freeze-snapshot-display", dest="freeze_snapshot_display", action="store_false",
                        help="Keep live camera view after snapshot inference.")
    parser.add_argument("--auto-reinfer-after-motion", dest="auto_reinfer_after_motion", action="store_true",
                        default=USER_SETTINGS["auto_reinfer_after_motion"],
                        help="After pick motion finishes, discard old snapshot and infer again after the view settles.")
    parser.add_argument("--no-auto-reinfer-after-motion", dest="auto_reinfer_after_motion", action="store_false",
                        help="Keep old snapshot target after robot motion. Not recommended when the cloth is disturbed.")
    parser.add_argument("--no-standby", action="store_true",
                        help="Do not automatically move arms to standby positions.")
    parser.add_argument("--imaging-standby", dest="imaging_standby", action="store_true",
                        default=USER_SETTINGS["imaging_standby"],
                        help="Move both arms to the side standby positions before imaging/snapshot so they do not occlude the clothing area.")
    parser.add_argument("--no-imaging-standby", dest="imaging_standby", action="store_false",
                        help="Disable automatic imaging-standby moves before snapshot/re-inference.")
    parser.add_argument("--imaging-standby-arrival-barrier", dest="imaging_standby_arrival_barrier", action="store_true",
                        default=USER_SETTINGS.get("imaging_standby_arrival_barrier", True),
                        help="motion_v2: require T:105 physical arrival of both camera-clear standby targets before snapshot is allowed.")
    parser.add_argument("--no-imaging-standby-arrival-barrier", dest="imaging_standby_arrival_barrier", action="store_false")
    parser.add_argument("--imaging-standby-arrival-timeout-s", type=float,
                        default=USER_SETTINGS.get("imaging_standby_arrival_timeout_s", 4.0))
    parser.add_argument("--imaging-standby-arrival-xy-tolerance-mm", type=float,
                        default=USER_SETTINGS.get("imaging_standby_arrival_xy_tolerance_mm", 35.0))
    parser.add_argument("--imaging-standby-arrival-z-tolerance-mm", type=float,
                        default=USER_SETTINGS.get("imaging_standby_arrival_z_tolerance_mm", 30.0))
    parser.add_argument("--imaging-standby-arrival-consecutive-samples", type=int,
                        default=USER_SETTINGS.get("imaging_standby_arrival_consecutive_samples", 1))
    parser.add_argument("--imaging-standby-arrival-poll-interval-s", type=float,
                        default=USER_SETTINGS.get("imaging_standby_arrival_poll_interval_s", 0.08))
    parser.add_argument("--imaging-standby-arrival-feedback-timeout-s", type=float,
                        default=USER_SETTINGS.get("imaging_standby_arrival_feedback_timeout_s", 0.45))
    parser.add_argument("--standby-z", type=float, default=USER_SETTINGS.get("standby_z", None),
                        help="Standby height. Step_a61 default is 230mm, i.e. old board-affine standby 180mm + 50mm.")
    parser.add_argument("--arm1-standby-board-x", type=float, default=USER_SETTINGS["arm1_standby_board_x"],
                        help="ARM1 standby board X. Default is the ID2/ID3 side edge, same as the provided reference code.")
    parser.add_argument("--arm1-standby-board-y", type=float, default=USER_SETTINGS["arm1_standby_board_y"],
                        help="ARM1 standby board Y. Default is the provided reference standby Y.")
    parser.add_argument("--arm2-standby-board-x", type=float, default=USER_SETTINGS["arm2_standby_board_x"],
                        help="ARM2 standby board X. Default is the ID0/ID1 side edge, same as the provided reference code.")
    parser.add_argument("--arm2-standby-board-y", type=float, default=USER_SETTINGS["arm2_standby_board_y"],
                        help="ARM2 standby board Y. Default is the provided reference standby Y.")
    parser.add_argument("--imaging-standby-direct-roarm", dest="imaging_standby_direct_roarm", action="store_true",
                        default=USER_SETTINGS.get("imaging_standby_direct_roarm", True),
                        help="Use directly taught RoArm XYZ/t standby coordinates for imaging/rejudge standby instead of board->RoArm affine standby.")
    parser.add_argument("--no-imaging-standby-direct-roarm", dest="imaging_standby_direct_roarm", action="store_false",
                        help="Use the old board-coordinate standby positions and affine conversion.")
    parser.add_argument("--imaging-standby-gripper-angle", type=float,
                        default=USER_SETTINGS.get("imaging_standby_gripper_angle", 1.57),
                        help="Gripper angle commanded before moving to imaging/rejudge standby. Use a slightly-open value to avoid forced-close heating.")
    parser.add_argument("--arm1-standby-roarm-x", type=float, default=USER_SETTINGS.get("arm1_standby_roarm_x", None),
                        help="ARM1 directly taught imaging standby RoArm X. Used when --imaging-standby-direct-roarm is enabled.")
    parser.add_argument("--arm1-standby-roarm-y", type=float, default=USER_SETTINGS.get("arm1_standby_roarm_y", None),
                        help="ARM1 directly taught imaging standby RoArm Y. Used when --imaging-standby-direct-roarm is enabled.")
    parser.add_argument("--arm1-standby-roarm-z", type=float, default=USER_SETTINGS.get("arm1_standby_roarm_z", None),
                        help="ARM1 directly taught imaging standby RoArm Z. If omitted, --standby-z or --z is used.")
    parser.add_argument("--arm1-standby-roarm-t", type=float, default=USER_SETTINGS.get("arm1_standby_roarm_t", None),
                        help="ARM1 directly taught imaging standby tool angle t. If omitted, marker-side or --t logic is used.")
    parser.add_argument("--arm2-standby-roarm-x", type=float, default=USER_SETTINGS.get("arm2_standby_roarm_x", None),
                        help="ARM2 directly taught imaging standby RoArm X. Used when --imaging-standby-direct-roarm is enabled.")
    parser.add_argument("--arm2-standby-roarm-y", type=float, default=USER_SETTINGS.get("arm2_standby_roarm_y", None),
                        help="ARM2 directly taught imaging standby RoArm Y. Used when --imaging-standby-direct-roarm is enabled.")
    parser.add_argument("--arm2-standby-roarm-z", type=float, default=USER_SETTINGS.get("arm2_standby_roarm_z", None),
                        help="ARM2 directly taught imaging standby RoArm Z. If omitted, --standby-z or --z is used.")
    parser.add_argument("--arm2-standby-roarm-t", type=float, default=USER_SETTINGS.get("arm2_standby_roarm_t", None),
                        help="ARM2 directly taught imaging standby tool angle t. If omitted, marker-side or --t logic is used.")
    parser.add_argument("--standby-parallel-to-marker-side", dest="standby_parallel_to_marker_side", action="store_true",
                        default=USER_SETTINGS.get("standby_parallel_to_marker_side", True),
                        help="At standby, set tool angle t parallel to ARM1 ID2-ID3 side and ARM2 ID0-ID1 side.")
    parser.add_argument("--no-standby-parallel-to-marker-side", dest="standby_parallel_to_marker_side", action="store_false")
    parser.add_argument("--arm1-standby-t-offset", type=float, default=USER_SETTINGS.get("arm1_standby_t_offset", 0.0),
                        help="Extra radian offset added to ARM1 standby-parallel t. Use +/-1.5708 if the wrist is 90deg off.")
    parser.add_argument("--arm2-standby-t-offset", type=float, default=USER_SETTINGS.get("arm2_standby_t_offset", 0.0),
                        help="Extra radian offset added to ARM2 standby-parallel t. Use +/-1.5708 if the wrist is 90deg off.")

    parser.add_argument("--grip-z", type=float, default=USER_SETTINGS["grip_z"], help="Common grip/contact z. More negative z usually means lower descent.")
    parser.add_argument("--arm1-grip-z", type=float, default=USER_SETTINGS["arm1_grip_z"],
                        help="ARM1-only grip/contact z override. Example: --arm1-grip-z -125")
    parser.add_argument("--arm2-grip-z", type=float, default=USER_SETTINGS["arm2_grip_z"],
                        help="ARM2-only grip/contact z override. Example: --arm2-grip-z -120")
    parser.add_argument("--grip-approach-z", type=float, default=USER_SETTINGS["grip_approach_z"])
    parser.add_argument("--grip-lift-z", type=float, default=USER_SETTINGS["grip_lift_z"],
                        help="Common lift z after gripping. Less negative / higher value usually lifts more.")
    parser.add_argument("--arm1-grip-lift-z", type=float, default=USER_SETTINGS["arm1_grip_lift_z"],
                        help="ARM1-only lift z override after close. Example: --arm1-grip-lift-z -25")
    parser.add_argument("--arm2-grip-lift-z", type=float, default=USER_SETTINGS["arm2_grip_lift_z"],
                        help="ARM2-only lift z override after close. Example: --arm2-grip-lift-z -25")
    parser.add_argument("--grip-open", type=float, default=USER_SETTINGS["grip_open"])
    parser.add_argument("--grip-close", type=float, default=USER_SETTINGS["grip_close"])
    parser.add_argument("--grip-hold", type=float, default=USER_SETTINGS["grip_hold"])
    parser.add_argument("--safe-gripper", type=float, default=USER_SETTINGS["safe_gripper"])
    parser.add_argument("--startup-open", action="store_true", default=True,
                        help="Open the ARM1 gripper immediately after serial connection. Default ON.")
    parser.add_argument("--no-startup-open", dest="startup_open", action="store_false",
                        help="Do not send the startup gripper-open command.")
    parser.add_argument("--startup-open-wait", type=float, default=0.80,
                        help="Wait time after startup gripper-open command.")
    parser.add_argument("--relax-after-lift", action="store_true", default=False,
                        help="After lift, relax to --post-lift-gripper angle. Use only if the cloth stays held.")
    parser.add_argument("--post-lift-gripper", type=float, default=None,
                        help="Optional relaxed gripper angle after lift. Default: same as --grip-hold.")
    parser.add_argument("--grip-spd", type=float, default=0.0)
    parser.add_argument("--grip-acc", type=float, default=0.0)
    parser.add_argument("--grip-open-wait", type=float, default=2.00)
    parser.add_argument("--grip-down-wait", type=float, default=0.60)
    parser.add_argument("--grip-contact-wait", type=float, default=0.20)
    parser.add_argument("--grip-close-repeat", type=int, default=2)
    parser.add_argument("--grip-close-wait", type=float, default=2.00)
    parser.add_argument("--grip-close-settle", type=float, default=2.00)

    parser.add_argument("--place-after-lift", dest="place_after_lift", action="store_true",
                        default=USER_SETTINGS["place_after_lift"],
                        help="After lift, place the cloth back down before retracting. Default from USER_SETTINGS.")
    parser.add_argument("--no-place-after-lift", dest="place_after_lift", action="store_false",
                        help="Old behavior: lift only and keep holding.")
    parser.add_argument("--place-same-xy", dest="place_same_xy", action="store_true",
                        default=USER_SETTINGS["place_same_xy"],
                        help="Place back at the same board XY as the grasp point. Recommended for step1.")
    parser.add_argument("--no-place-same-xy", dest="place_same_xy", action="store_false",
                        help="Use --place-board-x/--place-board-y instead of same-XY place.")
    parser.add_argument("--place-open-wait", type=float, default=USER_SETTINGS["place_open_wait"])
    parser.add_argument("--place-settle-wait", type=float, default=USER_SETTINGS["place_settle_wait"])
    parser.add_argument("--place-retract-after-open", dest="place_retract_after_open", action="store_true",
                        default=USER_SETTINGS["place_retract_after_open"])
    parser.add_argument("--no-place-retract-after-open", dest="place_retract_after_open", action="store_false")

    parser.add_argument("--auto-place", action="store_true", help="Legacy: After lift, place at board center/custom point. Default OFF.")
    parser.add_argument("--place-board-x", type=float, default=None)
    parser.add_argument("--place-board-y", type=float, default=None)
    parser.add_argument("--place-z", type=float, default=USER_SETTINGS["place_z"])
    parser.add_argument("--place-hover-z", type=float, default=USER_SETTINGS["place_hover_z"])

    args = parser.parse_args(argv)
    print(
        "[V51-WAITOPT-V1] "
        f"stillness={float(args.settle_seconds):.2f}s/{int(args.settle_min_frames)}frames "
        f"standby_settle={float(USER_SETTINGS.get('auto_wrinkle_standby_settle_s', 0.15)):.2f}s "
        f"internal_rejudge_delay={float(args.auto_x_internal_rejudge_delay_s):.2f}s "
        f"standby_poll={float(args.imaging_standby_arrival_poll_interval_s):.2f}s "
        f"center_release_settle={float(args.center_circumcenter_release_settle_s):.2f}s "
        "burst_frames=UNCHANGED"
    )
    stage2_external_control = stage2_control is not None
    if stage2_external_control:
        args.no_window = True
        args.no_terminal_control = True
        args.vla_dataset_recording = False
        args.vla_control_panel_enable = False
        args.micro_unfold_model_data_recording = False
        args.standalone_full_auto_execute = True
        args.micro_unfold_production_auto_enable = True
        args.pose_rotate_boundary_lazy_pair_plan = True
        # V51-ROTATE-LAZY-V1 remains ON by default from parser/controller, but unlike
        # the older boundary flag we intentionally do not force it here so an explicit
        # rollback request can survive into embedded Main.
        # v44 production policy: never pre-freeze unused LONG_PULL motions in embedded mode.
        # Keep this explicit instead of relying on parser defaults/config overrides.
        args.vla_long_pull_lazy_prefreeze_enable = True
        args.vla_micro_unfold_v42_full_e156_fallback_enable = False
        print("[UPPER-V51-EMBEDDED] headless=True shared_camera=True full_auto=True micro_production_auto=True long_pull_lazy=True pose_lazy=True full_e156=False")
    _rotate_lazy_env = str(os.environ.get("TONGSPAM_V51_ROTATE_LAZY", "")).strip().lower()
    if _rotate_lazy_env in {"0", "false", "off", "no"}:
        args.pose_rotate_lazy_pair_plan_all_reliable = False
    elif _rotate_lazy_env in {"1", "true", "on", "yes"}:
        args.pose_rotate_lazy_pair_plan_all_reliable = True
    print(
        "[V51-ROTATE-LAZY-V1] "
        f"reliable_current_pair_planning={'ON_DEMAND' if bool(args.pose_rotate_lazy_pair_plan_all_reliable) else 'LEGACY_EAGER_OUTSIDE_BOUNDARY'} "
        "rollback=--no-pose-rotate-lazy-pair-plan-all-reliable or TONGSPAM_V51_ROTATE_LAZY=0"
    )
    try:
        cca_threshold_patch_state = _a148_finalize_cca_threshold_patch_state(
            cca_threshold_patch_state, args, argv
        )
    except ValueError as e:
        parser.error(f"invalid effective CCA threshold profile: {e}")
    # v43 production AUTO: human supervision/data-collection code remains available, but it is
    # inactive by default so READY MICRO can flow through the existing full-auto physical
    # approval path.  Shadow/debug logging is intentionally left ON and all physical/frozen
    # plan safety checks remain authoritative.  --no-micro-unfold-production-auto restores
    # the legacy v42 behavior controlled by the individual recording/review flags.
    if bool(getattr(args, "micro_unfold_production_auto_enable", True)):
        _v43_forced_off = []
        for _name in (
            "vla_dataset_recording",
            "micro_unfold_model_data_recording",
            "micro_failure_annotation_enable",
            "micro_hard_negative_collection",
            "micro_hard_negative_review_before_micro",
        ):
            if bool(getattr(args, _name, False)):
                _v43_forced_off.append(_name)
            setattr(args, _name, False)
        print(
            "[V43-MICRO-PRODUCTION-AUTO] human VLA/MICRO collection-review gates=OFF; "
            "READY MICRO uses existing full-auto approval; shadow/debug logging + hard safety remain ON"
            + (f" | overridden={_v43_forced_off}" if _v43_forced_off else "")
        )

    if bool(getattr(args, "vla_dataset_recording", False)) and bool(getattr(args, "auto_x_action3_auto_execute", True)):
        # Dataset integrity: the operator must have a chance to accept/correct every
        # physical macro decision before execution. This changes orchestration only.
        setattr(args, "auto_x_action3_auto_execute", False)
        print("[VLA-DATA-POLICY] ACTION3 auto-execution disabled; every physical action requires Enter/Space")

    if cv2 is None:
        raise RuntimeError(f"OpenCV (cv2) is required for camera execution: {_CV2_IMPORT_ERROR!r}")

    auto_x_debug_logger = AutoXDebugLogger(base_dir=args.auto_x_log_dir, enabled=bool(args.auto_x_log))
    _pipeline_v2.configure(auto_x_debug_logger._orig_stdout)
    auto_x_debug_logger.install()
    auto_x_debug_logger.clear_old_logs()
    atexit.register(auto_x_debug_logger.close)
    atexit.register(_pipeline_v2.close)
    _a148_log_cca_threshold_patch_state(cca_threshold_patch_state)

    if args.display:
        os.environ["DISPLAY"] = str(args.display)
        print(f"[WINDOW] DISPLAY forced: {os.environ['DISPLAY']}")
    elif (not args.no_window) and (not os.environ.get("DISPLAY")) and platform.system().lower().startswith("linux"):
        os.environ["DISPLAY"] = ":0"
        print("[WINDOW] DISPLAY was empty; defaulting to :0")

    cfg = load_required_config(args.config)

    # Calibration-source policy: match the working D50/D56 behavior.
    # The folding-board config is authoritative. A separate affine cache is loaded
    # ONLY when the operator explicitly supplies --calib-cache. This prevents a
    # script-local vla/.../dual_roarm_affine_cache.json from silently overriding or
    # filling calibration data from a different board coordinate definition.
    if str(args.calib_cache or "").strip():
        args.calib_cache = os.path.abspath(os.path.expanduser(str(args.calib_cache)))
        affine_cache_state = load_affine_cache_into_config(cfg, args.calib_cache)
    else:
        args.calib_cache = ""
        affine_cache_state = {
            "loaded": False,
            "source": "config",
            "path": "",
            "reason": "separate affine cache disabled; config is authoritative",
            "created_at_unix": None,
        }
        print(f"[AFFINE] using calibration embedded in config: {os.path.abspath(args.config)}")

    print(f"[CALIB-PATH] board config (authoritative): {os.path.abspath(args.config)}")
    print(f"[CALIB-PATH] homography: {os.path.abspath(args.hfile)}")
    print(f"[CALIB-PATH] affine-cache override: {args.calib_cache if args.calib_cache else 'DISABLED'}")

    # Dual-arm step1 test mode:
    # - ARM1(ID2/ID3 쪽, 오른쪽) -> /dev/roarm_1
    # - ARM2(ID0/ID1 쪽, 왼쪽)  -> /dev/roarm_2
    cfg["dual_roarm"]["arm1"]["port"] = str(args.arm1_port)
    cfg["dual_roarm"]["arm2"]["port"] = str(args.arm2_port)
    cfg["dual_roarm"].setdefault("workspace", {})
    cfg["dual_roarm"]["workspace"]["step1_enabled"] = bool(args.workspace_step1)
    cfg["dual_roarm"]["workspace"]["dead_half_width"] = float(args.workspace_dead_half_width)
    print(f"[PORT] ARM1 ID2/ID3 side uses {cfg['dual_roarm']['arm1']['port']}")
    print(f"[PORT] ARM2 ID0/ID1 side uses {cfg['dual_roarm']['arm2']['port']}")

    if args.split_board_x is not None:
        cfg["dual_roarm"]["split_board_x"] = float(args.split_board_x)
    print("[CONFIG] startup runtime overrides are memory-only; shared config was NOT saved")

    required_ids = [int(x) for x in cfg["aruco"].get("required_ids", [0, 1, 2, 3])]
    min_bx, max_bx, min_by, max_by = board_bounds(cfg)
    split_x = float(cfg["dual_roarm"].get("split_board_x", (min_bx + max_bx) / 2.0))
    print(f"[BOARD] bounds x=[{min_bx:.1f},{max_bx:.1f}], y=[{min_by:.1f},{max_by:.1f}], split_x={split_x:.1f}")
    dead_half = float(cfg["dual_roarm"].get("workspace", {}).get("dead_half_width", USER_SETTINGS["workspace_dead_half_width"]))
    print(f"[BOARD] STEP1 workspace: ARM2 x <= {split_x - dead_half:.1f}, BLOCK {split_x - dead_half:.1f} < x < {split_x + dead_half:.1f}, ARM1 x >= {split_x + dead_half:.1f}")

    # H loading is deferred until the runtime camera geometry is prepared so an
    # undistorted Homography can never be silently paired with raw camera coordinates.
    deferred_h_load = bool(args.load_h)
    latest_H = None
    homography_locked = False
    latest_raw_H: Optional[np.ndarray] = None

    send_enabled = bool(args.send) and not bool(args.dry_run)
    arms: Dict[str, Optional[RoArmSerial]] = {"arm1": None, "arm2": None}
    if args.send:
        for arm_key in ("arm1", "arm2"):
            a_cfg = cfg["dual_roarm"][arm_key]
            port_path = str(a_cfg["port"])
            if not os.path.exists(port_path):
                print(f"[SERIAL-WARN] {arm_key.upper()} port does not exist in this environment: {port_path}")
                print("              Check udev rule, Docker --device/--privileged, or run: ls -l /dev/roarm_*")
            arms[arm_key] = RoArmSerial(port_path, int(a_cfg.get("baudrate", 115200)), label=arm_key.upper())
            if arms[arm_key] is not None:
                arms[arm_key].echo_enabled = bool(getattr(args, "serial_send_log", False))
            print(f"[SERIAL] {arm_key.upper()} connected: {port_path}")
    else:
        print("[MODE] --send not set. Robot commands will not be sent.")

    z_default = float(args.z if args.z is not None else cfg["dual_roarm"]["arm1"].get("safe_hover_z", 180.0))
    spd_default = float(args.speed if args.speed is not None else cfg["dual_roarm"]["arm1"].get("move_speed", 0.12))
    t_default = float(args.t if args.t is not None else cfg["dual_roarm"]["arm1"].get("tool_t_rad", 3.14))
    safe_gripper = float(args.safe_gripper if args.safe_gripper is not None else args.grip_open)
    approach_z = float(args.grip_approach_z if args.grip_approach_z is not None else z_default)
    lift_z = float(args.grip_lift_z if args.grip_lift_z is not None else z_default)
    standby_z = float(args.standby_z if args.standby_z is not None else z_default)

    # Prevent heat at startup: do not leave the extended gripper forced closed.
    # The default safe_gripper equals --grip-open unless explicitly overridden.
    if send_enabled and args.startup_open:
        for _arm_key in ("arm1", "arm2"):
            if arms.get(_arm_key) is not None:
                print(f"[STARTUP] opening {_arm_key.upper()} gripper to safe angle={safe_gripper:.3f} to avoid forced full-close heating")
                arms[_arm_key].torque_on()
                arms[_arm_key].set_gripper(safe_gripper, spd=args.grip_spd, acc=args.grip_acc, delay=args.startup_open_wait)

    cam_idx = int(cfg.get("camera_index", 0) if args.camera is None else args.camera)
    width = int(cfg.get("camera_width", 1280))
    height = int(cfg.get("camera_height", 720))
    backend = args.backend or cfg.get("camera_backend", "v4l2")
    external_camera_mode = external_frame_provider is not None
    if external_camera_mode:
        cap = ExternalFrameProviderCapture(external_frame_provider, width, height)
        print("[INTEGRATED-CAMERA] shared provider ACTIVE; physical VideoCapture open/release BYPASSED")
    else:
        cap = open_camera(cam_idx, width, height, backend)
    if not cap.isOpened():
        if external_camera_mode:
            raise RuntimeError("Integration-owned shared camera provider is not alive")
        raise RuntimeError(f"Cannot open camera index {cam_idx}")

    camera_controls_metadata: Dict[str, Any]
    if external_camera_mode:
        try:
            if hasattr(external_frame_provider, "integration_camera_controls_metadata"):
                camera_controls_metadata = dict(external_frame_provider.integration_camera_controls_metadata() or {})
            else:
                camera_controls_metadata = {}
        except Exception:
            camera_controls_metadata = {}
        camera_controls_metadata.setdefault("enabled", True)
        camera_controls_metadata.setdefault("source", "V22_INTEGRATION_CAMERA_OWNER")
        camera_controls_metadata.setdefault("device", f"/dev/video{cam_idx}")
        camera_controls_metadata.setdefault("declared_controls", {})
        camera_controls_metadata.setdefault("actual_controls", {})
        camera_controls_metadata.setdefault("mismatches", [])
        print("[INTEGRATED-CAMERA] main owns camera controls; upper_runtime_v51 will not write V4L2 controls")
    elif bool(getattr(args, "camera_controls_enable", True)):
        try:
            camera_controls_metadata = apply_camera_controls_json(
                str(args.camera_controls_json), f"/dev/video{cam_idx}",
                strict=bool(getattr(args, "camera_controls_strict", True)),
            )
        except Exception as exc:
            cap.release()
            raise RuntimeError(f"ELP camera controls profile is not usable: {exc}") from exc
    else:
        camera_controls_metadata = {
            "enabled": False, "profile_path": os.path.abspath(os.path.expanduser(str(args.camera_controls_json))),
            "profile_sha256": _sha256_file_quiet(str(args.camera_controls_json)), "device": f"/dev/video{cam_idx}",
            "declared_controls": {}, "actual_controls": {}, "mismatches": [],
        }
        print("[CAMERA-CONTROL-WARN] startup controls profile disabled")

    # Let exposure/white-balance settle after V4L2 values are applied.
    stabilize_n = max(0, int(getattr(args, "camera_controls_stabilization_frames", 12)))
    for _ in range(stabilize_n):
        ok_stable, _stable_frame = cap.read()
        if not ok_stable:
            break
    probe_ok, probe_raw = cap.read()
    if not probe_ok or probe_raw is None:
        cap.release()
        raise RuntimeError(f"Camera index {cam_idx} opened but initial frame read failed")
    actual_size = (int(probe_raw.shape[1]), int(probe_raw.shape[0]))
    try:
        actual_fps = float(cap.get(cv2.CAP_PROP_FPS))
    except Exception:
        actual_fps = 0.0
    try:
        fourcc_code = int(round(float(cap.get(cv2.CAP_PROP_FOURCC))))
    except Exception:
        fourcc_code = 0
    fourcc_text = "".join(chr((fourcc_code >> (8 * i)) & 0xFF) for i in range(4)).replace("\x00", "").strip()
    camera_capture_metadata = {
        "width": int(actual_size[0]),
        "height": int(actual_size[1]),
        "fps": float(actual_fps),
        "fourcc": fourcc_text or None,
        "fourcc_code": int(fourcc_code),
        "backend": "V22_SHARED_PROVIDER" if external_camera_mode else str(backend),
        "source": "V22_UI_SOLE_CAMERA_OWNER" if external_camera_mode else "LOCAL_VIDEOCAPTURE",
    }
    print(
        f"[CAMERA] requested={width}x{height} actual={actual_size[0]}x{actual_size[1]} "
        f"fps={actual_fps:.3f} fourcc={fourcc_text or fourcc_code} backend={backend}"
    )
    print(f"[CALIB-PATH] camera undistort: {os.path.abspath(os.path.expanduser(str(args.camera_calibration)))}")

    camera_undistorter = None
    camera_geometry_metadata: Dict[str, Any]
    if bool(getattr(args, "camera_undistort", True)):
        if CameraUndistorter is None:
            cap.release()
            raise RuntimeError(
                f"camera_undistort.py import failed: {_CAMERA_UNDISTORT_IMPORT_ERROR!r}. "
                "Place camera_undistort.py beside vla_0808.py."
            )
        try:
            camera_undistorter = CameraUndistorter(
                str(args.camera_calibration),
                alpha=float(args.camera_undistort_alpha),
                strict_size=bool(args.camera_undistort_strict_size),
            )
            camera_info = camera_undistorter.prepare(actual_size)
        except CameraCalibrationError as exc:
            cap.release()
            raise RuntimeError(f"ELP camera calibration is not usable: {exc}") from exc
        camera_geometry_metadata = camera_info.to_metadata()
        camera_geometry_metadata["camera_model"] = "ELP_OV2710"
        camera_geometry_metadata["calibration_sha256"] = _sha256_file_quiet(str(args.camera_calibration))
        print(f"[CAMERA-UNDISTORT] READY {camera_undistorter.status_line()}")
        print("[CAMERA-UNDISTORT] raw live preview/stillness/stale-watch; corrected ArUco + finalized analysis snapshots")
    else:
        camera_geometry_metadata = {
            "camera_model": "ELP_OV2710_RAW", "undistort_enabled": False,
            "calibration_path": os.path.abspath(os.path.expanduser(str(args.camera_calibration))),
            "calibration_sha256": _sha256_file_quiet(str(args.camera_calibration)),
            "calibration_id": "DISABLED", "input_size": list(actual_size),
            "output_size": list(actual_size), "alpha": None,
        }
        print("[CAMERA-UNDISTORT-WARN] DISABLED. Do not reuse an undistorted Homography cache.")

    @_pipeline_v2.timed('snapshot_undistortion', 'observation')
    def make_analysis_frame(raw_frame: np.ndarray, reason: str = "analysis snapshot") -> np.ndarray:
        if raw_frame is None or not isinstance(raw_frame, np.ndarray):
            raise RuntimeError(f"{reason}: raw frame is invalid")
        if camera_undistorter is None:
            return raw_frame.copy()
        try:
            return camera_undistorter.correct(raw_frame)
        except CameraCalibrationError as exc:
            raise RuntimeError(f"{reason}: ELP remap failed: {exc}") from exc

    if deferred_h_load:
        if os.path.exists(args.hfile):
            loaded_H, loaded_raw_H, loaded_geometry = load_homography_bundle(args.hfile)
            # The validated folding-board H predates camera_geometry metadata.
            # Missing metadata alone must never force an unnecessary R->L recalibration.
            # If metadata exists, explicit geometry mismatches are still rejected.
            geometry_ok, geometry_reason = homography_camera_geometry_matches(
                loaded_geometry, camera_geometry_metadata, allow_legacy=True,
            )
            if not geometry_ok:
                cap.release()
                raise RuntimeError(
                    f"Homography camera geometry mismatch: {geometry_reason}. "
                    "Reset/relock H with R then L using the current ELP camera geometry."
                )
            latest_H = loaded_H
            latest_raw_H = loaded_raw_H
            homography_locked = True
            if isinstance(loaded_geometry, dict):
                print(f"[H] camera geometry verified: {geometry_reason}")
            else:
                print("[H] validated legacy folding-board H accepted; camera_geometry metadata is not required")
        else:
            print(f"[H] --load-h requested, but cache file not found: {args.hfile}")
            print("[H] Show all 4 ArUco markers and press L, or keep --auto-lock enabled.")

    dictionary = get_dictionary(cfg["aruco"].get("dictionary", "DICT_4X4_50"))
    detector = make_detector(dictionary)

    show_window = not bool(args.no_window)
    skip_unused_headless_overlay = (
        os.environ.get("TONGSPAM_V51_HEADLESS_OVERLAY_SKIP", "0") == "1"
        and not show_window and bool(args.no_terminal_control)
    )
    window = "Dual RoArm Step1 Workspace Pick - Live ReInfer"
    if show_window:
        try:
            cv2.namedWindow(window)
        except cv2.error as e:
            print("[WINDOW-ERROR] Cannot create OpenCV window.")
            print("[WINDOW-ERROR] Run on Jetson host first: DISPLAY=:0 xhost +local:root")
            print("[WINDOW-ERROR] Then: sudo docker exec -it -e DISPLAY=:0 roarm_aruco bash")
            print(f"[WINDOW-ERROR] DISPLAY={os.environ.get('DISPLAY', '<unset>')}")
            print(e)
            if args.fallback_no_window:
                show_window = False
                print("[WINDOW] fallback no-window mode")
            else:
                raise

    ready_status_panel_window = "AUTO-X Ready To Rotate Status"
    ready_status_panel_enabled = bool(show_window and getattr(args, "auto_x_ready_status_panel", True))
    if ready_status_panel_enabled:
        try:
            cv2.namedWindow(ready_status_panel_window, cv2.WINDOW_NORMAL)
            cv2.resizeWindow(ready_status_panel_window,
                             max(520, int(getattr(args, "auto_x_ready_status_panel_width", 700))),
                             max(600, int(getattr(args, "auto_x_ready_status_panel_height", 760))))
            cv2.moveWindow(ready_status_panel_window,
                           int(getattr(args, "auto_x_ready_status_panel_x", 1310)),
                           int(getattr(args, "auto_x_ready_status_panel_y", 0)))
        except cv2.error as e:
            ready_status_panel_enabled = False
            print(f"[A110-READY-PANEL-WARN] separate status window disabled: {e}")

    vla_control_panel_window = "VLA Dataset Controls"
    vla_control_panel_enabled = bool(
        show_window and (
            (getattr(args, "vla_dataset_recording", False) and getattr(args, "vla_control_panel_enable", True))
            or getattr(args, "micro_hard_negative_collection", True)
        )
    )
    if vla_control_panel_enabled:
        try:
            cv2.namedWindow(vla_control_panel_window, cv2.WINDOW_NORMAL)
            cv2.resizeWindow(vla_control_panel_window,
                             max(760, int(getattr(args, "vla_control_panel_width", 980))),
                             max(500, int(getattr(args, "vla_control_panel_height", 500))))
            cv2.moveWindow(vla_control_panel_window,
                           int(getattr(args, "vla_control_panel_x", 930)),
                           int(getattr(args, "vla_control_panel_y", 770)))
        except cv2.error as e:
            vla_control_panel_enabled = False
            print(f"[VLA-DATA-PANEL-WARN] control window disabled: {e}")
    if bool(getattr(args, "micro_hard_negative_collection", True)):
        print(f"[MICRO-HN-V38] independent collector=ON vla_dataset_recording={bool(getattr(args,'vla_dataset_recording',False))} panel={vla_control_panel_enabled} | READY MICRO review: Y=OK N=NOT_MICRO")

    terminal = TerminalKeyReader(enabled=not args.no_terminal_control, raw=not args.terminal_line_mode)
    terminal.start()

    grasp_model = None
    if args.grasp_model:
        if YOLO is None:
            raise RuntimeError("ultralytics is not installed. Install it or run without --grasp-model.")
        if not os.path.exists(str(args.grasp_model)):
            print(f"[YOLO-WARN] model file not found: {args.grasp_model}")
            print("[YOLO-WARN] Run with --grasp-model <path> or edit USER_SETTINGS['grasp_model'].")
        else:
            print(f"[YOLO] Loading model: {args.grasp_model}")
            grasp_model = YOLO(args.grasp_model, task=args.grasp_task)
    pose_model = None
    pose_path: Optional[str] = None
    if args.pose_model and bool(args.pose_rotation_preview):
        if YOLO is None:
            raise RuntimeError("ultralytics is not installed. Install it or run without --pose-model.")
        pose_path_candidates = [str(args.pose_model)]
        if not os.path.isabs(str(args.pose_model)):
            pose_path_candidates.append(os.path.join(os.getcwd(), str(args.pose_model)))
            pose_path_candidates.append(os.path.join("/workspace/models", str(args.pose_model)))
        pose_path = next((x for x in pose_path_candidates if os.path.exists(x)), None)
        if pose_path is None:
            print(f"[POSE-WARN] pose model file not found: {args.pose_model}")
            print("[POSE-WARN] Expected current directory, absolute path, or /workspace/models. Pose rotation preview disabled.")
        else:
            print(f"[POSE] Loading pose model: {pose_path}")
            pose_model = YOLO(pose_path, task="pose")
    if bool(getattr(args, "auto_x_rotate_enable", True)) and pose_model is None:
        print(
            "[A152-ROTATE-STARTUP-WARN] independent ROTATE_PULL/SHEAR is enabled, "
            "but no pose model is loaded. Pose recovery may use mask-axis only after bounded failure handling; otherwise ROTATE will REJUDGE/BLOCK without legacy fallback."
        )

    grasp_classes = set(x.strip() for x in args.grasp_classes.split(",") if x.strip())
    selected_grasp_key = args.grasp_target
    latest_candidates = []
    latest_candidate = None
    latest_point = None
    latest_dual_plan = None
    latest_dual_status = "not computed"
    latest_coarse_plan = None
    latest_coarse_status = "not computed"
    latest_fallback_status = "not used"
    latest_segmentation_source = "NONE"
    # Last mask area trusted for fallback-color sanity checks.  Only semantic YOLO
    # or empty-board bgdiff observations update this value; color fallback never does.
    fallback_last_trusted_area_px: Optional[float] = None
    latest_spread_eval: Optional[Dict[str, Any]] = None
    spread_eval_history: List[Dict[str, Any]] = []
    coarse_action_axis_override: Optional[str] = None
    coarse_action_stretch_distance_override: Optional[float] = None
    coarse_weak_bad_streak = 0
    coarse_x_dominant_streak = 0
    coarse_last_direction_kind: Optional[str] = None
    coarse_same_direction_streak = 0
    coarse_x_since_last_press = 0
    latest_targeted_press_plan: Optional[Dict[str, Any]] = None
    latest_targeted_press_status = "not computed"
    latest_wrinkle_heatmap_plan: Optional[Dict[str, Any]] = None
    latest_wrinkle_heatmap_status = "not computed"
    wrinkle_press_history: List[Dict[str, Any]] = []
    latest_boundary_plan: Optional[Dict[str, Any]] = None
    latest_boundary_status = "not computed"
    latest_marker_fill_plan: Optional[Dict[str, Any]] = None
    latest_marker_fill_status = "not computed"
    latest_pose_rotation_plan: Optional[Dict[str, Any]] = None
    latest_pose_rotation_status = "not computed"
    # v44: current-snapshot context for lazy ROTATE pair-plan construction in the reliable 8..14deg confirmation band.
    pose_rotation_deferred_context: Optional[Dict[str, Any]] = None
    # Step_a25: full garment mask used for display and for '/' overflow planning.
    # This mask is intentionally NOT clipped to the ArUco board. It should include
    # cloth protruding outside the 0-1-2-3 marker rectangle.
    latest_full_garment_mask: Optional[np.ndarray] = None
    latest_full_garment_status = "not computed"
    # Step_a27: raw YOLO segmentation mask in full camera coordinates.
    # This is never clipped to the ArUco board and is used only for display/debug.
    latest_yolo_raw_mask: Optional[np.ndarray] = None
    latest_yolo_raw_status = "not computed"
    # Step_a29: latest / contact-drag plan shown on the OpenCV screen.
    latest_variable_overflow_plan: Optional[Dict[str, Any]] = None
    latest_variable_overflow_status = "not computed"
    # Allows the post-motion rejudge snapshot after arms have already returned to standby,
    # even though the / automation worker thread is still technically running.
    variable_overflow_rejudge_capture_allowed = False
    # Step_a31: true only while / is intentionally waiting for a normal stillness-gated
    # post-motion rejudge snapshot. All other robot motions block snapshot capture.
    variable_overflow_rejudge_waiting_for_still = False
    debug_segmentation_mask_overlay = bool(getattr(args, "debug_segmentation_mask_overlay", False))
    fallback_empty_gray: Optional[np.ndarray] = None
    shared_empty_board_state: Optional[EmptyBoardState] = None
    fallback_empty_lab: Optional[np.ndarray] = None
    # Raw copy is used only by the raw-coordinate stale-watch path.
    fallback_empty_raw_gray: Optional[np.ndarray] = None
    fallback_empty_frame_count = 0
    frame_count = 0
    auto_pick_done = False
    auto_pick_buffer: List[List[float]] = []

    motion_lock = threading.RLock()
    motion_thread: Optional[threading.Thread] = None
    motion_busy = False
    motion_approval_handoff = None  # Display provenance of the admitted worker, not a new owner.
    # True only while key-4 AUTO CENTER is running its closed-loop drag cycles.
    # It prevents stale SELECT/SPREAD/press overlays from competing with MO/SIDE-PICK.
    smart_reposition_running = False
    torque_released = False
    arms_in_imaging_standby = False
    # Last exact RoArm XYZ targets commanded by move_arm_to_standby().
    imaging_standby_last_targets: Dict[str, Optional[Dict[str, float]]] = {"arm2": None, "arm1": None}
    last_auto_standby_try_at = 0.0

    # Snapshot-grasp state. Default is ON unless --live-grasp is used.
    snapshot_mode = not bool(args.live_grasp)
    snapshot_ready = False
    # snapshot_frame is the corrected analysis frame; snapshot_raw_frame preserves exact camera input.
    snapshot_frame: Optional[np.ndarray] = None
    snapshot_raw_frame: Optional[np.ndarray] = None
    snapshot_canvas: Optional[np.ndarray] = None
    yolo_busy = False
    inference_serial = 0
    _vla_board_transform_cache = None  # one observation only; matrix stays private to this helper
    _wrinkle_texture_cache = None
    _wrinkle_texture_generation = 0
    _wrinkle_texture_lock = threading.Lock()

    def _invalidate_wrinkle_texture_cache():
        nonlocal _wrinkle_texture_cache, _wrinkle_texture_generation
        with _wrinkle_texture_lock:
            _wrinkle_texture_generation += 1
            _wrinkle_texture_cache = None

    def _set_wrinkle_texture_snapshot(frame):
        nonlocal snapshot_frame, _wrinkle_texture_cache, _wrinkle_texture_generation
        with _wrinkle_texture_lock:
            snapshot_frame = frame
            _wrinkle_texture_generation += 1
            _wrinkle_texture_cache = None

    force_snapshot_reason: Optional[str] = None
    # vla_0841: explicit wait outcome survives a late worker cleanup/reset so a
    # technical timeout can never race back into the NO_ACTION_CANDIDATE branch.
    latest_coarse_wait_outcome = "IDLE"
    latest_coarse_wait_detail = ""
    # A/R may cancel an AUTO-X observation while its already-started YOLO worker
    # is still running.  Keep A139's old_serial+yolo_busy handoff, and request one
    # cache cleanup when that cancelled worker exits (no generation/CAS transplant).
    auto_x_cancelled_yolo_cleanup_required = False
    # Step_a110: physical 3~5-frame burst becomes one logical AUTO-X snapshot.
    # Other forced snapshots keep A109's original single-frame behavior.
    force_snapshot_burst_frames: List[np.ndarray] = []
    force_snapshot_burst_reason: Optional[str] = None
    last_snapshot_burst_count = 1
    # Step_a46: X/auto-pose workers run inside the motion thread, but their first step
    # is only camera re-inference before any robot movement. Allow those explicit
    # pre-motion snapshot requests while motion_busy is true.
    force_snapshot_during_motion_allowed = False
    wait_cloth_after_no_candidates = False
    no_candidate_baseline_gray: Optional[np.ndarray] = None
    snapshot_reference_gray: Optional[np.ndarray] = None
    snapshot_foreground_state: Optional[Dict[str, Any]] = None
    target_stale_frames = 0
    target_removed_frames = 0
    target_changed_frames = 0
    target_stale_armed_at = 0.0
    stable_prev_gray: Optional[np.ndarray] = None
    stable_since: Optional[float] = None
    stable_low_motion_frames = 0
    cloth_baseline_gray: Optional[np.ndarray] = None
    cloth_baseline_frames = 0
    cloth_seen = False
    # Step_a59: AUTO-X decision overlay shown on the OpenCV live view.
    # Step_a60: direct imaging-standby RoArm Z defaults raised by +50mm for clearer/higher standby.
    # Updated after each one-snapshot rejudgment so the operator can see which action
    # the planner selected before the robot begins that action.
    latest_auto_x_decision_text = ""
    latest_auto_x_decision_detail = ""
    latest_auto_x_decision_until = 0.0
    # Step_a105: the right side of the bottom AUTO-X panel explains why the
    # garment still failed the finish gate after the most recently executed action.
    latest_auto_x_post_action_title = ""
    latest_auto_x_post_action_detail_1 = ""
    latest_auto_x_post_action_detail_2 = ""
    last_auto_x_executed_action = ""
    last_auto_x_executed_at = 0.0
    pending_auto_x_action: Optional[Dict[str, Any]] = None
    pending_selection_owner = None
    pending_approval_owner = None
    # A66: after X judgment, ENTER/SPACE must never fall through to normal pick.
    # This prevents ACTION1 CENTER_CIRCUMCENTER from being mistaken for pick/place when the operator confirms too early or when no pending action exists.
    auto_x_manual_judge_active = False
    # A140 continuous-cycle orchestration.  Motion helpers remain the A139 ones;
    # this controller only schedules fresh judgments and classifies their result.
    auto_x_controller = A140AutoXController(
        internal_rejudge_enable=bool(getattr(args, "auto_x_internal_rejudge_enable", True)),
        internal_rejudge_max_attempts=int(getattr(args, "auto_x_internal_rejudge_max_attempts", 2)),
        internal_rejudge_delay_s=float(getattr(args, "auto_x_internal_rejudge_delay_s", 0.10)),
    )
    auto_x_latency = A140LatencyTracker()
    # v13: independent of A140's per-label counter.  This guard counts every
    # automatically scheduled INTERNAL rejudge while garment_motion_count is
    # unchanged, so changing labels (POSE -> FALLBACK -> LATE) cannot create an
    # infinite loop.  A real garment motion or garment-cycle reset clears it.
    auto_x_same_motion_rejudge_guard: Dict[str, int] = {
        "motion_count": 0,
        "count": 0,
    }
    auto_x_action_standby_attempt_serial = 0
    auto_x_action_standby_command_serial = 0
    # v5: command transmission is not physical arrival. MICRO_UNFOLD uses this
    # separate serial so its recovery latch cannot be cleared by a standby command
    # that timed out before both arms actually reached camera-clear standby.
    auto_x_action_standby_verified_serial = 0
    auto_x_action_vertical_clear_serial = 0
    auto_x_action_release_serial = 0
    auto_x_action_command_serial = 0
    auto_x_current_release_serial_baseline = 0
    auto_x_action_parallel_errors: List[str] = []
    # vla_0822: execution-time provenance for any ROTATE WAYPOINT near-limit soft-pass.
    pose_rotate_arrival_soft_pass_events: List[Dict[str, Any]] = []
    # A physical action that stopped before the complete safety envelope
    # (full release + same-XY vertical clear + both-arm standby) latches recovery.
    # Standalone/manual v51 keeps the historical '.' acknowledgement policy.
    # Embedded/main integration replaces X/. with one automatic recovery sequence:
    # FULL OPEN -> existing verified standby -> clear latch/state -> fresh judgment.
    auto_x_physical_recovery_required = False
    auto_x_physical_recovery_reason = ""
    upper_embedded_auto_recovery_pending_judge = False
    upper_embedded_auto_recovery_reason = ""
    upper_embedded_auto_recovery_count = 0

    _MAIN_LATENCY_FORWARD_EVENTS = frozenset({
        "physical_action_end",
        "standby_command_start",
        "standby_command_end",
        "snapshot_request",
        "burst_start",
        "burst_complete",
        "inference_start",
        "inference_complete",
        "planner_start",
        "planner_end",
    })

    def _main_latency_forward(event: str, **meta) -> None:
        if external_frame_provider is None or str(event) not in _MAIN_LATENCY_FORWARD_EVENTS:
            return
        fn = getattr(external_frame_provider, "latency_event", None)
        if not callable(fn):
            return
        try:
            fn(f"V51_{str(event).upper()}", **meta)
        except Exception:
            pass

    def _a140_latency_mark(name: str, **meta) -> None:
        _pipeline_v2.legacy_mark(name, **meta)
        auto_x_latency.mark(name, **meta)
        _main_latency_forward(str(name), **meta)

    def _a140_latency_mark_once(name: str, **meta) -> None:
        _pipeline_v2.legacy_mark(name, **meta)
        auto_x_latency.mark_once(name, **meta)
        _main_latency_forward(str(name), **meta)

    def _a140_latency_print_cycle(outcome_action: str) -> None:
        line = auto_x_latency.finish_line(str(outcome_action))
        if line:
            print(line)

    def _a140_note_vertical_clear(label: str) -> None:
        nonlocal auto_x_action_vertical_clear_serial
        _pipeline_v2.note_clear(label)
        auto_x_action_vertical_clear_serial += 1
        _a140_latency_mark("vertical_clear_end", vertical_clear_label=str(label))

    def _a140_note_release(label: str) -> None:
        nonlocal auto_x_action_release_serial
        _pipeline_v2.note_release(label)
        auto_x_action_release_serial += 1
        _a140_latency_mark("release_end", release_label=str(label))

    def _a140_note_action_command(label: str) -> None:
        nonlocal auto_x_action_command_serial
        if send_enabled and auto_x_controller.state == "EXECUTING":
            auto_x_action_command_serial += 1
            _a140_latency_mark_once("physical_action_start", command_label=str(label))

            # V20: expose only the macro that has actually reached the physical
            # command-sending path.  Never expose model/planner candidates.
            if stage2_control is not None and stage2_control.is_cycle_active():
                published = False
                with auto_x_controller._lock:
                    with motion_lock:
                        handoff = motion_approval_handoff
                        if (handoff is None or not handoff["entered"] or not handoff["reserved"]
                                or motion_thread is not handoff["thread"]):
                            return
                        pending = handoff["execution_pending"]
                    if (not auto_x_controller.is_current(pending.get("a140_cycle_epoch", -1))
                            or auto_x_controller.state != "EXECUTING"):
                        return
                    dispatch_action = str(pending.get("action") or "").strip()
                    macro = _vla_macro_action(dispatch_action)
                    allowed = {"CENTER", "SPREAD", "LONG_PULL", "MICRO_UNFOLD", "ROTATE", "ORTHO_SPREAD"}
                    if macro in allowed and stage2_control.current_action() != macro:
                        stage2_control.publish_action(macro)
                        published = True
                if published:
                    print(
                        f"[UPPER-ACTION-TELEMETRY-EXEC] macro={macro} "
                        f"dispatch={dispatch_action} firstCommand={label}",
                        flush=True,
                    )

    def _a140_require_physical_recovery(reason: str) -> None:
        nonlocal auto_x_physical_recovery_required, auto_x_physical_recovery_reason
        nonlocal auto_x_manual_judge_active, pending_auto_x_action
        auto_x_physical_recovery_required = True
        auto_x_physical_recovery_reason = str(reason)
        pending_auto_x_action = None
        auto_x_manual_judge_active = True
        _a140_set_outer_overlay(
            "AUTO-X PHYSICAL RECOVERY REQUIRED - PRESS .",
            f"manual safety check required; X/standby blocked: {reason}",
            hold_s=3600.0,
        )

    def _a140_clear_physical_recovery(reason: str) -> None:
        nonlocal auto_x_physical_recovery_required, auto_x_physical_recovery_reason
        if auto_x_physical_recovery_required:
            print(f"[A140-PHYSICAL-RECOVERY-CLEARED] {reason}")
        auto_x_physical_recovery_required = False
        auto_x_physical_recovery_reason = ""

    def _a140_note_standby_commanded(label: str, both_arms: bool) -> None:
        nonlocal auto_x_action_standby_attempt_serial, auto_x_action_standby_command_serial
        auto_x_action_standby_attempt_serial += 1
        if both_arms:
            auto_x_action_standby_command_serial += 1

    def _a140_note_standby_verified(label: str) -> None:
        nonlocal auto_x_action_standby_verified_serial
        auto_x_action_standby_verified_serial += 1
        print(f"[A140-STANDBY-VERIFIED] serial={auto_x_action_standby_verified_serial} label={label}")

    def _a140_standby_ready_for_action(action_name: str, command_before: int, verified_before: int) -> bool:
        commanded = bool(int(auto_x_action_standby_command_serial) > int(command_before))
        if str(action_name) == "MICRO_UNFOLD_E156":
            return bool(commanded and int(auto_x_action_standby_verified_serial) > int(verified_before))
        return commanded

    def _a140_set_outer_overlay(text: str, detail: str = "", hold_s: float = 60.0) -> None:
        nonlocal latest_auto_x_decision_text, latest_auto_x_decision_detail, latest_auto_x_decision_until
        latest_auto_x_decision_text = str(text)
        latest_auto_x_decision_detail = str(detail)
        latest_auto_x_decision_until = time.time() + max(0.0, float(hold_s))

    def _set_auto_x_overlay(text: str = "", detail: str = "", hold_s: float = 60.0) -> None:
        """VLA/UI-safe outer overlay helper.

        The A150 planner also has a planner-local helper with the same historical name.
        VLA panel callbacks live outside that nested scope, so they must use this
        outer wrapper instead of raising NameError after a human override click.
        """
        _a140_set_outer_overlay(str(text)[:120], str(detail)[:150], hold_s=float(hold_s))

    def _a140_disarm_continuous_cycle(reason: str, terminal_state: str = "IDLE") -> None:
        nonlocal pending_auto_x_action, auto_x_manual_judge_active
        _invalidate_wrinkle_texture_cache()
        auto_x_controller.disarm(str(reason), str(terminal_state))
        pending_auto_x_action = None
        auto_x_manual_judge_active = False
        _pipeline_v2.cancel(reason)

